def _valor_vazio_ou_nao_informado(valor) -> bool:
    texto = str(valor or "").strip()
    return not texto or normalizar_texto(texto) in {"NAO INFORMADO", "NÃO INFORMADO", "NONE", "NAN", "NULL", "-", "—"}


def espaco_oficial_por_tutor(nome_tutor: str) -> str:
    nome_norm = normalizar_texto(nome_tutor)
    for chave, espaco in TUTORIA_ESPACOS_OFICIAIS:
        if normalizar_texto(chave) in nome_norm:
            return espaco
    return ""


def aplicar_config_tutoria_oficial(tutoria_dict: dict) -> dict:
    """Aplica a referência informada pelo usuário sem apagar dados já preenchidos.
    - Turno 1: 6º, 7º, 8º, 9º, 3ºA e 3ºB.
    - Espaços oficiais por professor/tutor.
    - Horário e dia padrão quando estiverem vazios.
    """
    base = normalizar_base_tutoria(tutoria_dict or {})
    for tutor, dados in base.items():
        espaco = espaco_oficial_por_tutor(tutor)
        if espaco and _valor_vazio_ou_nao_informado(dados.get("espaco", "")):
            dados["espaco"] = espaco
        if _valor_vazio_ou_nao_informado(dados.get("horario", "")):
            dados["horario"] = TUTORIA_HORARIO_PADRAO_TURNO1
        if _valor_vazio_ou_nao_informado(dados.get("dia", "")):
            dados["dia"] = TUTORIA_DIA_PADRAO_TURNO1
    return normalizar_base_tutoria(base)

def mensagem_erro_tutoria_supabase(erro: Exception) -> str:
    texto = str(erro)
    resposta = getattr(erro, "response", None)
    if resposta is not None and getattr(resposta, "status_code", None) == 404:
        return "A tabela de tutoria não está disponível no Supabase agora. O cadastro local continua salvo normalmente."
    return f"Não foi possível sincronizar a tutoria com o Supabase: {texto}"

def estrutura_tutoria_vazia(nome: str = "", tipo: str = "Professor(a)") -> dict:
    return {
        "nome": str(nome or "").strip(),
        "tipo": normalizar_perfil_tutoria(tipo),
        "espaco": "",
        "horario": "",
        "dia": "",
        "alunos": []
    }

def normalizar_alunos_tutoria(alunos_raw) -> list:
    alunos = []
    for item in alunos_raw or []:
        if isinstance(item, dict):
            nome = str(item.get("nome", "")).strip()
            serie = formatar_turma_eletiva(str(item.get("serie", "")).strip())
            ra = "".join(ch for ch in str(item.get("ra", "")) if ch.isdigit())
        else:
            nome = str(item or "").strip()
            serie = ""
            ra = ""
        if not nome:
            continue
        aluno = {"nome": nome, "serie": serie}
        if ra:
            aluno["ra"] = ra
        alunos.append(aluno)
    return alunos

def normalizar_base_tutoria(tutoria_raw: dict | None) -> dict:
    base = {}
    for tutor, dados in (tutoria_raw or {}).items():
        nome_tutor = str(tutor or "").strip()
        if not nome_tutor:
            continue
        if isinstance(dados, dict):
            registro = estrutura_tutoria_vazia(
                nome=nome_tutor,
                tipo=normalizar_perfil_tutoria(dados.get("tipo", "Professor(a)"))
            )
            registro["espaco"] = str(dados.get("espaco", "")).strip() or espaco_padrao_tutoria_por_responsavel(nome_tutor)
            registro["horario"] = str(dados.get("horario", "")).strip()
            registro["dia"] = str(dados.get("dia", "")).strip()
            registro["alunos"] = normalizar_alunos_tutoria(dados.get("alunos", []))
        else:
            registro = estrutura_tutoria_vazia(nome=nome_tutor)
            registro["espaco"] = espaco_padrao_tutoria_por_responsavel(nome_tutor)
            registro["alunos"] = normalizar_alunos_tutoria(dados)
        base[nome_tutor] = registro
    return base

def total_estudantes_tutoria(tutoria_dict: dict | None) -> int:
    """Conta vínculos de estudantes na Tutoria sem depender da tela.
    Usado como proteção para não sobrescrever uma base com estudantes
    por uma base apenas de responsáveis/metadados.
    """
    try:
        base = normalizar_base_tutoria(tutoria_dict or {})
        return int(sum(len(dados.get("alunos", []) or []) for dados in base.values()))
    except Exception:
        return 0


def obter_registro_tutoria(tutoria_dict: dict, tutor: str) -> dict:
    nome_tutor = str(tutor or "").strip()
    if not nome_tutor:
        return estrutura_tutoria_vazia()
    return normalizar_base_tutoria({nome_tutor: tutoria_dict.get(nome_tutor, {})}).get(
        nome_tutor,
        estrutura_tutoria_vazia(nome=nome_tutor)
    )

def mesclar_tutoria_com_metadados(base_tutoria: dict, referencia_tutoria: dict) -> dict:
    base = normalizar_base_tutoria(base_tutoria)
    referencia = normalizar_base_tutoria(referencia_tutoria)
    for tutor, dados in referencia.items():
        if tutor not in base:
            base[tutor] = dados
            continue
        for campo in ("tipo", "espaco", "horario", "dia"):
            if str(dados.get(campo, "")).strip():
                base[tutor][campo] = str(dados.get(campo, "")).strip()
    return base


def _valor_primeiro_campo(row, aliases: list[str]) -> str:
    """Lê o primeiro campo existente e preenchido em uma linha/DataFrame.
    Evita perda de dados quando a tabela usa nomes antigos ou diferentes.
    """
    for alias in aliases:
        try:
            if alias in row.index:
                valor = str(row.get(alias, "") or "").strip()
                if valor and valor.lower() not in ("nan", "none", "null"):
                    return valor
        except Exception:
            continue
    return ""

def converter_metadados_professores_para_tutoria(df_professores_base: pd.DataFrame) -> dict:
    """Monta metadados de tutoria a partir da tabela professores, quando houver colunas compatíveis.
    Serve como proteção para não sumirem Espaço, Horário e Dia caso a tabela tutoria venha incompleta.
    """
    base = {}
    if df_professores_base is None or df_professores_base.empty:
        return base
    aliases_nome = ["nome", "professora", "professor", "responsavel", "responsável", "tutor", "tutora"]
    aliases_tipo = ["tipo", "perfil", "cargo", "funcao", "função"]
    aliases_espaco = ["espaco", "espaço", "espaco_usado", "espaço_usado", "sala", "ambiente", "local"]
    aliases_horario = ["horario", "horário", "hora", "periodo", "período"]
    aliases_dia = ["dia", "dia_semana", "dia_da_semana", "semana"]
    for _, row in df_professores_base.iterrows():
        nome = _valor_primeiro_campo(row, aliases_nome)
        if not nome:
            continue
        registro = estrutura_tutoria_vazia(nome=nome)
        tipo = _valor_primeiro_campo(row, aliases_tipo)
        espaco = _valor_primeiro_campo(row, aliases_espaco)
        horario = _valor_primeiro_campo(row, aliases_horario)
        dia = _valor_primeiro_campo(row, aliases_dia)
        if tipo:
            registro["tipo"] = normalizar_perfil_tutoria(tipo)
        if espaco:
            registro["espaco"] = espaco
        if horario:
            registro["horario"] = horario
        if dia:
            registro["dia"] = dia
        base[nome] = registro
    return normalizar_base_tutoria(base)

def mesclar_multiplas_fontes_tutoria(*fontes: dict) -> dict:
    """Mescla fontes preservando metadados preenchidos e alunos já existentes."""
    resultado = {}
    for fonte in fontes:
        fonte_norm = normalizar_base_tutoria(fonte or {})
        for tutor, dados in fonte_norm.items():
            if tutor not in resultado:
                resultado[tutor] = estrutura_tutoria_vazia(nome=tutor)
            for campo in ("tipo", "espaco", "horario", "dia"):
                valor_atual = str(resultado[tutor].get(campo, "") or "").strip()
                valor_novo = str(dados.get(campo, "") or "").strip()
                if valor_novo and (not valor_atual or valor_atual == "Professor(a)"):
                    resultado[tutor][campo] = valor_novo
            alunos_existentes = {
                (normalizar_texto(a.get("nome", "")), formatar_turma_eletiva(a.get("serie", "")))
                for a in resultado[tutor].get("alunos", [])
            }
            for aluno in dados.get("alunos", []) or []:
                chave = (normalizar_texto(aluno.get("nome", "")), formatar_turma_eletiva(aluno.get("serie", "")))
                if chave[0] and chave not in alunos_existentes:
                    resultado[tutor].setdefault("alunos", []).append(aluno)
                    alunos_existentes.add(chave)
    return normalizar_base_tutoria(resultado)

def carregar_tutoria_local(fallback: dict | None = None) -> dict:
    try:
        if os.path.exists(TUTORIA_CACHE_ARQUIVO):
            with open(TUTORIA_CACHE_ARQUIVO, "r", encoding="utf-8") as f:
                return normalizar_base_tutoria(json.load(f))
    except Exception as e:
        logger.error(f"Erro ao carregar cache local da tutoria: {e}")
    return normalizar_base_tutoria(fallback or {})

def salvar_tutoria_local(tutoria_dict: dict):
    """Salva a Tutoria localmente com backup automático antes de sobrescrever.

    Proteção importante: nunca grava uma versão vazia por cima de um arquivo
    local que ainda tenha estudantes. Antes de qualquer substituição, cria uma
    cópia em data/tutoria_backups/.
    """
    try:
        base_nova = normalizar_base_tutoria(tutoria_dict)
        os.makedirs(os.path.dirname(TUTORIA_CACHE_ARQUIVO), exist_ok=True)

        base_antiga = {}
        if os.path.exists(TUTORIA_CACHE_ARQUIVO):
            try:
                with open(TUTORIA_CACHE_ARQUIVO, "r", encoding="utf-8") as f:
                    base_antiga = normalizar_base_tutoria(json.load(f))
            except Exception:
                base_antiga = {}

        total_antigo = total_estudantes_tutoria(base_antiga)
        total_novo = total_estudantes_tutoria(base_nova)
        if total_antigo > 0 and total_novo == 0:
            logger.warning("Protecao Tutoria: bloqueado salvar cache vazio por cima de cache com estudantes.")
            return

        if os.path.exists(TUTORIA_CACHE_ARQUIVO):
            try:
                backup_dir = DATA_DIR / "tutoria_backups"
                backup_dir.mkdir(parents=True, exist_ok=True)
                stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                shutil.copy2(TUTORIA_CACHE_ARQUIVO, backup_dir / f"tutoria_backup_{stamp}.json")
            except Exception as e:
                logger.warning(f"Nao foi possivel criar backup local da tutoria: {e}")

        with open(TUTORIA_CACHE_ARQUIVO, "w", encoding="utf-8") as f:
            json.dump(base_nova, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.error(f"Erro ao salvar cache local da tutoria: {e}")


def _nome_responsavel_tutoria_tem_nome_sobrenome(nome: str) -> bool:
    """Retorna True somente para nomes completos de responsáveis.

    Regra prática para a Tutoria: nomes com apenas uma palavra, como
    "Erika", "Elaine" ou "Igor", são considerados cadastros parciais e
    não devem aparecer nas listas principais. Eles só são preservados se
    ainda houver vínculo sem destino de nome completo equivalente.
    """
    texto = str(nome or "").strip()
    if not texto:
        return False
    partes = [p for p in re.split(r"\s+", texto) if p]
    if len(partes) < 2:
        return False
    if len(re.sub(r"[^A-Za-zÀ-ÿ]", "", texto)) < 5:
        return False
    return True


def _primeiro_nome_tutoria(nome: str) -> str:
    partes = [p for p in re.split(r"\s+", str(nome or "").strip()) if p]
    return normalizar_texto(partes[0]) if partes else ""


def _nomes_professores_cadastrados_validos(df_professores_base: pd.DataFrame | None = None) -> list[str]:
    nomes = []
    try:
        if df_professores_base is not None and not df_professores_base.empty and "nome" in df_professores_base.columns:
            nomes = df_professores_base["nome"].dropna().astype(str).str.strip().tolist()
    except Exception:
        nomes = []
    nomes = [n for n in nomes if _nome_responsavel_tutoria_tem_nome_sobrenome(n)]
    return sorted(set(nomes), key=lambda x: normalizar_texto(x))


def normalizar_responsaveis_tutoria_para_exibicao(tutoria_dict: dict, df_professores_base: pd.DataFrame | None = None) -> dict:
    """Remove/mescla cadastros parciais de responsáveis sem apagar vínculos.

    - Se existir "Erika" e também "Erika Paula Viana Watanabe", os alunos
      vinculados em "Erika" são movidos para o nome completo e o cadastro curto
      sai da tela.
    - Se o nome curto não tiver alunos, ele é removido.
    - Se o nome curto tiver alunos e não houver nome completo correspondente,
      ele é mantido internamente para não perder dados, mas não deve ser usado
      nas listas principais.
    """
    base = normalizar_base_tutoria(tutoria_dict)
    if not base:
        return {}

    nomes_prof = _nomes_professores_cadastrados_validos(df_professores_base)
    candidatos_completos = {normalizar_texto(n): n for n in nomes_prof}
    for nome in base.keys():
        if _nome_responsavel_tutoria_tem_nome_sobrenome(nome):
            candidatos_completos.setdefault(normalizar_texto(nome), nome)

    # índice por primeiro nome para achar destino provável.
    por_primeiro = {}
    for nome_completo in candidatos_completos.values():
        por_primeiro.setdefault(_primeiro_nome_tutoria(nome_completo), []).append(nome_completo)

    resultado = dict(base)
    alterou = False
    for nome in list(base.keys()):
        if _nome_responsavel_tutoria_tem_nome_sobrenome(nome):
            continue
        dados_curto = resultado.get(nome, estrutura_tutoria_vazia(nome=nome))
        alunos_curto = normalizar_alunos_tutoria(dados_curto.get("alunos", []))
        primeiro = _primeiro_nome_tutoria(nome)
        destinos = sorted(por_primeiro.get(primeiro, []), key=lambda x: (len(x), normalizar_texto(x)))
        destino = destinos[0] if destinos else ""
        if destino and destino != nome:
            dados_destino = resultado.get(destino, estrutura_tutoria_vazia(nome=destino))
            # preserva metadados do destino; só completa se estiver vazio.
            for campo in ["tipo", "espaco", "horario", "dia"]:
                if not str(dados_destino.get(campo, "")).strip() and str(dados_curto.get(campo, "")).strip():
                    dados_destino[campo] = dados_curto.get(campo, "")
            existentes = normalizar_alunos_tutoria(dados_destino.get("alunos", []))
            chaves = {
                ("".join(ch for ch in str(a.get("ra", "")) if ch.isdigit()), normalizar_texto(a.get("nome", "")), turma_para_comparacao(a.get("serie", "")))
                for a in existentes
            }
            for aluno in alunos_curto:
                chave = (
                    "".join(ch for ch in str(aluno.get("ra", "")) if ch.isdigit()),
                    normalizar_texto(aluno.get("nome", "")),
                    turma_para_comparacao(aluno.get("serie", "")),
                )
                if chave not in chaves:
                    existentes.append(aluno)
                    chaves.add(chave)
            dados_destino["alunos"] = existentes
            resultado[destino] = dados_destino
            resultado.pop(nome, None)
            alterou = True
        elif not alunos_curto:
            resultado.pop(nome, None)
            alterou = True
        # Se houver alunos e não houver destino completo, preserva internamente.

    if alterou:
        try:
            salvar_tutoria_local(resultado)
        except Exception:
            pass
    return normalizar_base_tutoria(resultado)


def nomes_responsaveis_validos_tutoria(tutoria_dict: dict, df_professores_base: pd.DataFrame | None = None, incluir_sem_alunos: bool = True) -> list[str]:
    base = normalizar_base_tutoria(tutoria_dict)
    nomes = [str(n).strip() for n in base.keys() if _nome_responsavel_tutoria_tem_nome_sobrenome(n)]
    # Mantém também professores cadastrados na página de professores para permitir novo vínculo.
    if incluir_sem_alunos:
        nomes.extend(_nomes_professores_cadastrados_validos(df_professores_base))
    vistos = set()
    saida = []
    for nome in sorted(nomes, key=lambda x: normalizar_texto(x)):
        chave = normalizar_texto(nome)
        if chave and chave not in vistos:
            saida.append(nome)
            vistos.add(chave)
    return saida

