# ======================================================
# IA CONVIVA — FUNÇÕES AUXILIARES DO RELATÓRIO
# ======================================================
# Estas funções precisam existir ANTES de render_ia_conviva_relatorio().
# Sem elas o Streamlit quebra com NameError em _campos_relatorio_ia().

def ia_conviva_configurada() -> bool:
    """Retorna True quando a chave da IA online está configurada."""
    return bool(str(GEMINI_API_KEY or "").strip())


def _campos_relatorio_ia() -> dict:
    """Mapeia os campos visuais do relatório para as chaves do session_state."""
    return {
        "Desenvolvimento acadêmico": "relatorio_desenvolvimento",
        "Observações comportamentais e socioemocionais": "relatorio_comportamental",
        "Estratégias e encaminhamentos": "relatorio_estrategias",
        "Pontos de atenção complementares": "relatorio_pontos_manuais",
        "Descrição do ponto grave": "relatorio_ponto_grave",
    }


def _textos_campos_relatorio() -> dict:
    """Lê os textos atuais digitados no formulário de relatório."""
    campos = _campos_relatorio_ia()
    return {
        nome_campo: str(st.session_state.get(chave, "") or "").strip()
        for nome_campo, chave in campos.items()
    }


def _escolher_tarefa_ia_automatica(campo_escolhido: str, texto_base: str = "") -> str:
    """Escolhe uma tarefa padrão coerente com o campo selecionado."""
    campo = str(campo_escolhido or "").lower()
    if "encaminhamento" in campo or "estratég" in campo or "estrateg" in campo:
        return "Sugerir comunicados ou encaminhamentos para a Família"
    if "escrita corrida" in campo:
        return "Gerar escrita corrida do relatório"
    if "ponto grave" in campo or "grave" in campo:
        return "Transformar em registro de ocorrência (Placon)"
    return "Melhorar escrita pedagógica (Relatório/Família)"


def montar_escrita_corrida_relatorio(contexto_relatorio: dict, textos_campos: dict) -> str:
    """Monta um texto-base com os dados do relatório para a IA transformar em escrita corrida."""
    contexto_relatorio = contexto_relatorio or {}
    aluno = str(contexto_relatorio.get("aluno", "") or "").strip() or "Estudante não informado"
    turma = str(contexto_relatorio.get("turma", "") or "").strip() or "Turma não informada"
    situacao = str(contexto_relatorio.get("situacao_geral", "") or "").strip()
    frequencia = str(contexto_relatorio.get("frequencia", "") or "").strip()

    partes = [f"Estudante: {aluno}", f"Turma: {turma}"]
    if situacao:
        partes.append(f"Situação geral: {situacao}")
    if frequencia:
        partes.append(f"Frequência: {frequencia}")

    for titulo, texto in (textos_campos or {}).items():
        texto = str(texto or "").strip()
        if texto:
            partes.append(f"{titulo}: {texto}")

    return "\n".join(partes).strip()


def _limpar_texto_para_ia(texto: str) -> str:
    """Remove termos claramente inadequados antes de enviar para a IA, sem alterar o registro original."""
    texto_limpo = str(texto or "")
    for termo in TERMOS_OFENSIVOS_RELATORIO:
        texto_limpo = re.sub(re.escape(termo), "[termo inadequado]", texto_limpo, flags=re.IGNORECASE)
    return texto_limpo.strip()


def _texto_tem_termo_inadequado(texto: str) -> bool:
    texto_norm = normalizar_texto(texto or "")
    texto_bruto = str(texto or "").lower()
    return (
        any(normalizar_texto(termo) in texto_norm for termo in TERMOS_OFENSIVOS_RELATORIO)
        or any(fragmento in texto_bruto for fragmento in ("pregui", "idiota", "burro", "incapaz", "relaxad", "desleixad", "brigu", "barulh", "excess", "desrespeit"))
    )


def _modelos_gemini_para_tentar() -> list[str]:
    """Tenta primeiro o modelo configurado e depois modelos atuais estáveis."""
    modelos = [
        str(GEMINI_MODEL or "").strip(),
        "gemini-2.5-flash",
        "gemini-flash-latest",
    ]
    vistos = set()
    finais = []
    for modelo in modelos:
        modelo = modelo.replace("models/", "").strip()
        if modelo and modelo not in vistos:
            vistos.add(modelo)
            finais.append(modelo)
    return finais


def _limpar_markdown_ia(texto: str) -> str:
    """Remove formatação Markdown que fica ruim dentro dos campos do relatório."""
    texto = str(texto or "").strip()
    texto = re.sub(r"\*\*(.*?)\*\*", r"\1", texto)
    texto = re.sub(r"^\s*#{1,6}\s*", "", texto, flags=re.MULTILINE)
    texto = re.sub(r"^\s*[-*]\s+", "", texto, flags=re.MULTILINE)
    texto = re.sub(r"\n{3,}", "\n\n", texto)
    return texto.strip()


def _saida_parece_incompleta(texto: str) -> bool:
    texto = str(texto or "").strip()
    if not texto:
        return True
    if len(texto) < 90:
        return True
    if texto[-1] not in ".!?":
        return True
    finais_fracos = (
        " que", " para", " com", " de", " do", " da", " das", " dos", " e", " ou",
        " pois", " porque", " quando", " conforme", " durante"
    )
    return texto.lower().endswith(finais_fracos)

def _saida_parece_generica(texto: str, texto_original: str = "") -> bool:
    """Evita respostas prontas quando a saída não preserva nenhum elemento concreto."""
    saida_norm = normalizar_texto(texto or "")
    original_norm = normalizar_texto(texto_original or "")
    if not saida_norm:
        return True
    frases_genericas = (
        "COM AS INFORMACOES DISPONIVEIS REGISTRAMOS QUE O ESTUDANTE NECESSITA",
        "SITUACAO ENVOLVENDO",
        "DEMANDOU INTERVENCAO IMEDIATA",
        "ENCAMINHAMENTOS NECESSARIOS",
        "ACOES CABIVEIS",
        "VISANDO PROMOVER",
        "COM VISTAS A",
        "FORTALECIMENTO DA CONVIVENCIA",
        "CONDUTA INCOMPATIVEL",
        "A EQUIPE SEGUIRA ACOMPANHANDO SEU DESENVOLVIMENTO E MANTERA DIALOGO",
    )
    if any(frase in saida_norm for frase in frases_genericas):
        return True
    if len(original_norm) < 30:
        return False

    stopwords = {
        "QUE", "COM", "PARA", "DOS", "DAS", "UMA", "POR", "NAO", "SER", "TER",
        "FOI", "SAO", "DEU", "FEZ", "MAS", "SUA", "SEU", "ELE", "ELA", "AOS",
        "NAS", "NOS", "DIA", "ANO", "ANOS", "SALA", "SALAS", "ALUNO", "ALUNA",
        "ALUNOS", "ALUNAS", "ESTUDANTE", "ESTUDANTES",
    }
    tokens_concretos = [
        t for t in re.findall(r"[A-Z0-9]{3,}", original_norm)
        if t not in stopwords
    ]
    if len(tokens_concretos) < 3:
        return False

    preservados = sum(1 for t in tokens_concretos[:24] if t in saida_norm)
    return preservados == 0


def _extrair_nomes_estudantes_contexto(contexto: str = "") -> list[str]:
    """Extrai nomes de estudantes do contexto JSON/textual enviado para a IA."""
    nomes = []
    try:
        dados = json.loads(contexto) if isinstance(contexto, str) and contexto.strip().startswith("{") else {}
        estudantes = dados.get("estudantes", []) if isinstance(dados, dict) else []
        for item in estudantes or []:
            nome = str(item or "").split(" - ")[0].strip()
            if nome and nome not in nomes:
                nomes.append(nome)
    except Exception:
        pass
    return nomes

def _formatar_lista_nomes(nomes: list[str]) -> str:
    nomes = [str(n or "").strip() for n in nomes or [] if str(n or "").strip()]
    if not nomes:
        return ""
    if len(nomes) == 1:
        return nomes[0]
    return ", ".join(nomes[:-1]) + " e " + nomes[-1]

# [limpeza] definição duplicada de _resposta_pedagogica_local removida; mantida a versão final.


def chamar_ia_conviva_online(texto: str, tarefa: str, contexto: str = "") -> str:
    """Chama a API Gemini para gerar sugestão pedagógica."""
    texto = str(texto or "").strip()
    if not texto:
        return "Digite um texto antes de usar a IA."

    if not ia_conviva_configurada():
        return _resposta_pedagogica_local(texto, tarefa, contexto)
    # Envia termos inadequados para a IA reescrever sem julgamento, sem perder o sentido do registro.
    instrucao = INSTRUCOES_TAREFAS_IA_RELATORIO.get(
        tarefa,
        str(tarefa or "Melhore a escrita em linguagem pedagógica.")
    )

    tokens_importantes = []
    for token in re.findall(r"[A-Za-zÀ-ÿ0-9]{3,}", texto):
        token_norm = normalizar_texto(token)
        if token_norm in {"QUE", "COM", "PARA", "DOS", "DAS", "UMA", "POR", "NAO", "ALUNOS", "ESTUDANTES"}:
            continue
        if token_norm not in [normalizar_texto(t) for t in tokens_importantes]:
            tokens_importantes.append(token)
        if len(tokens_importantes) >= 12:
            break
    instrucao_tokens = ""
    if tokens_importantes:
        instrucao_tokens = (
            "\nELEMENTOS DO RELATO QUE DEVEM APARECER NA REESCRITA: "
            + ", ".join(tokens_importantes)
            + ".\nPreserve esses elementos quando fizer sentido e não invente fatos novos."
        )
    nomes_contexto = _extrair_nomes_estudantes_contexto(contexto)
    instrucao_estudantes = ""
    if nomes_contexto and any(t in normalizar_texto(tarefa or "") for t in ("OCORR", "PLACON", "REGISTRO")):
        instrucao_estudantes = (
            "\nESTUDANTES SELECIONADOS QUE DEVEM SER CITADOS NOMINALMENTE NO REGISTRO: "
            + _formatar_lista_nomes(nomes_contexto)
            + ".\nUse os nomes de forma natural no texto, sem criar fatos novos."
        )

    prompt = f"""
{PROMPT_IA_CONVIVA_PEDAGOGICA}

TAREFA:
{instrucao}

CONTEXTO DO RELATÓRIO:
{contexto or 'Não informado'}

TEXTO ORIGINAL:
{_limpar_texto_para_ia(texto)}
{instrucao_tokens}
{instrucao_estudantes}

FORMATO OBRIGATÓRIO:
- Responda apenas com a versão pronta para uso escolar, em português do Brasil.
- Não use títulos, listas, bullets, numeração, markdown ou negrito.
- Produza um parágrafo pedagógico completo, claro e útil para relatório escolar.
- Use linguagem simples, humana e direta. Evite parecer texto de robô.
- Evite termos genéricos ou técnicos demais, como "engajamento", "alta demanda motora", "ambiente de aprendizagem" e "habilidades em desenvolvimento", salvo quando forem indispensáveis.
- Se o texto original tratar de fala excessiva, barulho, briga ou conduta, prefira linguagem regimental clara: combinados de convivência, regimento escolar, falas excessivas, atitudes em desacordo com a rotina escolar.
- Não explique que a frase original é inadequada; apenas entregue a reescrita.
- Não invente fatos, diagnósticos ou informações não fornecidas.
- Não escreva recomendações para o professor. Escreva como escola/professor falando com a família ou registrando no prontuário.
- Evite "recomenda-se". Prefira "a escola tem acompanhado", "temos observado", "será mantido acompanhamento", "solicitamos a parceria da família".
- Datas devem ser escritas em português do Brasil e no formato DD/MM/AAAA.
- Preserve nomes, locais, ações e consequências informadas no texto original.
- Quando houver estudantes selecionados no contexto, cite seus nomes no registro.
- Se o texto mencionar intervalo, corrida, esconder-se, agente de organização, coordenador ou retorno à sala, mantenha esses fatos no registro.
- Se perceber que sua resposta ficou genérica, refaça antes de responder.
""".strip()

    payload = {
        "contents": [
            {"parts": [{"text": prompt}]}
        ],
        "generationConfig": {
            "temperature": 0.20,
            "topP": 0.85,
            "maxOutputTokens": 900,
        },
    }

    ultimo_erro = ""
    try:
        for modelo in _modelos_gemini_para_tentar():
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{modelo}:generateContent"
            resposta = requests.post(
                url,
                headers={
                    "x-goog-api-key": GEMINI_API_KEY,
                    "Content-Type": "application/json",
                },
                json=payload,
                timeout=15,
            )
            if resposta.status_code != 200:
                ultimo_erro = f"{resposta.status_code} no modelo {modelo}"
                if resposta.status_code in (404, 429, 500, 502, 503, 504):
                    continue
                break
            dados = resposta.json()
            candidatos = dados.get("candidates") or []
            if not candidatos:
                ultimo_erro = f"sem candidato no modelo {modelo}"
                continue
            partes = candidatos[0].get("content", {}).get("parts", [])
            saida = "\n".join(str(p.get("text", "")) for p in partes if p.get("text"))
            saida = _limpar_markdown_ia(saida)
            finish_reason = str(candidatos[0].get("finishReason", "") or "")
            if (
                saida
                and normalizar_texto(saida) != normalizar_texto(texto)
                and finish_reason != "MAX_TOKENS"
                and not _saida_parece_incompleta(saida)
                and not _saida_parece_generica(saida, texto)
            ):
                saida_norm = normalizar_texto(saida)
                texto_norm_original = normalizar_texto(texto)
                saida_robotica = any(
                    termo in saida_norm
                    for termo in ("ENGAJAMENTO", "AMBIENTE DE APRENDIZAGEM", "ALTA DEMANDA MOTORA", "HABILIDADES EM DESENVOLVIMENTO")
                )
                caso_regimental = any(
                    termo in texto_norm_original
                    for termo in ("BARULH", "BRIGU", "BRIGA", "FALA DEMAIS", "EXCESS", "DESRESPEIT")
                )
                if saida_robotica and caso_regimental:
                    return _resposta_pedagogica_local(texto, tarefa, contexto)
                return saida
        return _resposta_pedagogica_local(texto, tarefa, contexto)
    except Exception as e:
        logger.warning(f"Falha ao conectar com IA online: {e}. Último erro: {ultimo_erro}")
        return _resposta_pedagogica_local(texto, tarefa, contexto)

# ======================================================
# BLOCO VISUAL DA IA NO RELATÓRIO
# ======================================================

def render_ia_conviva_relatorio(contexto_relatorio: dict):
    """Bloco visual da IA dentro do relatório do estudante."""

    st.markdown("### 🤖 IA Conviva Pedagógica Online")

    if ia_conviva_configurada():
        st.success(f"IA online configurada com Gemini ({GEMINI_MODEL}).")
    else:
        st.warning(
            "Configure GEMINI_API_KEY nos Secrets do Streamlit Cloud ou no arquivo .env para ativar a IA online."
        )

    opcoes_campo = _campos_relatorio_ia()
    opcoes_campo_ia = list(opcoes_campo.keys()) + [
        "Escrita corrida do relatório",
    ]

    campo_escolhido = st.selectbox(
        "Campo que a IA deve revisar",
        opcoes_campo_ia,
        key="ia_conviva_campo_relatorio"
    )

    textos_campos = _textos_campos_relatorio()

    if campo_escolhido == "Escrita corrida do relatório":
        texto_base = montar_escrita_corrida_relatorio(contexto_relatorio, textos_campos)
        chave_campo = "relatorio_escrita_corrida_atual"
    else:
        chave_campo = opcoes_campo[campo_escolhido]
        texto_base = textos_campos.get(campo_escolhido, "")

    tarefa_escolhida = _escolher_tarefa_ia_automatica(campo_escolhido, texto_base)

    texto_para_ia = st.text_area(
        "Texto que será enviado para a IA",
        value=texto_base,
        height=140,
        key=f"ia_conviva_texto_editavel_{gerar_chave_segura(campo_escolhido)}"
    )

    consulta_atual = f"{campo_escolhido}|{texto_para_ia}"
    if st.session_state.get("ia_conviva_ultima_consulta") != consulta_atual:
        st.session_state.pop("ia_conviva_resultado_relatorio", None)
        st.session_state.pop("ia_conviva_resultado_area", None)
        st.session_state.pop("ia_conviva_campo_destino", None)

    if st.button(
        "✨ Melhorar escrita com IA",
        type="primary",
        use_container_width=True,
        key="ia_conviva_gerar_btn"
    ):
        if not str(texto_para_ia or "").strip():
            st.warning("Preencha algum texto antes de usar a IA.")
        else:
            with st.spinner("A IA Conviva Pedagógica está preparando a sugestão..."):
                resultado = chamar_ia_conviva_online(
                    texto=texto_para_ia,
                    tarefa=tarefa_escolhida,
                    contexto=str(contexto_relatorio)
                )

            st.session_state["ia_conviva_resultado_relatorio"] = resultado
            st.session_state["ia_conviva_resultado_area"] = resultado
            st.session_state["ia_conviva_campo_destino"] = chave_campo
            st.session_state["ia_conviva_ultima_consulta"] = consulta_atual

    resultado = st.session_state.get("ia_conviva_resultado_relatorio", "")
    campo_destino = st.session_state.get("ia_conviva_campo_destino", chave_campo)

    if resultado:
        if st.session_state.get("ia_conviva_resultado_area") != resultado:
            st.session_state["ia_conviva_resultado_area"] = resultado
        st.text_area(
            "Sugestão da IA",
            height=220,
            key="ia_conviva_resultado_area"
        )

        col_aplicar, col_nova = st.columns([1, 1])
        with col_aplicar:
            if st.button(
                "✅ Aplicar sugestão no campo",
                use_container_width=True,
                key="ia_conviva_aplicar_sugestao_btn"
            ):
                st.session_state["ia_conviva_aplicar_pendente"] = {
                    "campo": campo_destino,
                    "texto": st.session_state.get("ia_conviva_resultado_area", resultado)
                }
                st.success("Sugestão preparada para aplicar ao campo.")
                st.rerun()
        with col_nova:
            if st.button("🔄 Nova consulta", use_container_width=True, key="ia_conviva_nova_consulta_btn"):
                st.session_state.pop("ia_conviva_resultado_relatorio", None)
                st.session_state.pop("ia_conviva_resultado_area", None)
                st.session_state.pop("ia_conviva_campo_destino", None)
                st.session_state.pop("ia_conviva_ultima_consulta", None)
                st.rerun()

