@st.cache_data(ttl=120)
def carregar_agendamentos_filtrado(data_ini: str, data_fim: str, espaco: str = None, professor: str = None) -> pd.DataFrame:
    try:
        path = "/rest/v1/agendamentos"
        # requests não permite chave duplicada no dict; montar como lista de tuplas
        params_list = [
            ("select", "id,data_agendamento,horario,espaco,turma,disciplina,prioridade,semanas,professor_nome,professor_email,status"),
            ("order", "data_agendamento.asc,horario.asc"),
            ("data_agendamento", f"gte.{data_ini}"),
            ("data_agendamento", f"lte.{data_fim}"),
        ]

        if espaco and espaco in ESPACOS_AGEND:
            params_list.append(("espaco", f"eq.{espaco}"))

        if professor:
            params_list.append(("professor_nome", f"eq.{professor}"))

        rows = _rest_get_agend(path, params=params_list)
        return pd.DataFrame(rows) if rows else pd.DataFrame()
        
    except Exception as e:
        st.warning(f"Falha ao consultar agendamentos: {e}")
        return pd.DataFrame()

def _rest_get_agend(path: str, params: dict = None, timeout: int = 20):
    url = f"{SUPABASE_URL}{path}"
    r = requests.get(url, headers=HEADERS, params=params or {}, timeout=timeout)
    r.raise_for_status()
    return r.json()

def salvar_agendamento_api(dados: dict):
    url = f"{SUPABASE_URL}/rest/v1/agendamentos"
    r = requests.post(url, json=dados, headers=HEADERS, timeout=20)
    # Compatibilidade: algumas bases não possuem a coluna 'tipo'
    if r.status_code >= 400 and "tipo" in str(dados).lower() and "'tipo' column" in r.text:
        dados_retry = dict(dados)
        dados_retry.pop("tipo", None)
        r = requests.post(url, json=dados_retry, headers=HEADERS, timeout=20)
    if r.status_code not in (200, 201):
        return False, f"{r.status_code} - {r.text}"
    return True, r.json()

def cancelar_agendamento_api(id_agend: str):
    url = f"{SUPABASE_URL}/rest/v1/agendamentos?id=eq.{id_agend}"
    r = requests.patch(url, json={"status": "CANCELADO"}, headers=HEADERS, timeout=20)
    return r.status_code in (200, 204), None

def excluir_agendamento_api(id_agend: str):
    url = f"{SUPABASE_URL}/rest/v1/agendamentos?id=eq.{id_agend}"
    r = requests.patch(url, json={"status": "EXCLUIDO_GESTAO"}, headers=HEADERS, timeout=20)
    return r.status_code in (200, 204), None

def verificar_conflito_api(data_yyyy_mm_dd: str, horario: str, espaco: str):
    try:
        path = f"/rest/v1/agendamentos?select=id,professor_nome,prioridade&data_agendamento=eq.{data_yyyy_mm_dd}&horario=eq.{horario}&espaco=eq.{espaco}&status=eq.ATIVO&limit=1"
        rows = _rest_get_agend(path)
        return rows[0] if rows else None
    except Exception:
        return None

def prof_list_agend(only_active: bool = True) -> pd.DataFrame:
    try:
        path = "/rest/v1/professores?select=id,nome,email,cargo&order=nome.asc"
        rows = _rest_get_agend(path)
        df = pd.DataFrame(rows) if rows else pd.DataFrame(columns=["id", "nome", "email", "cargo"])
        if not df.empty and 'cargo' in df.columns:
            df['status'] = 'ATIVO'
        return df
    except Exception:
        return pd.DataFrame(columns=["id", "nome", "email", "cargo", "status"])

def prof_upsert_agend(nome: str, email: str, status: str = "ATIVO"):
    payload = {"nome": (nome or "").strip(), "email": (email or "").strip(), "cargo": "Professor"}
    url = f"{SUPABASE_URL}/rest/v1/professores"
    headers_upsert = HEADERS.copy()
    headers_upsert["Prefer"] = "resolution=merge-duplicates,return=representation"
    r = requests.post(url, json=payload, headers=headers_upsert, timeout=20)
    return r.status_code in (200, 201), r.json() if r.status_code in (200, 201) else None
# ======================================================
# ELETIVAS — IMPORTAÇÃO EXCEL
# ======================================================

def carregar_eletivas_do_excel(caminho_arquivo: str, fallback: dict = None) -> dict:
    """Lê planilha XLSX de eletivas diretamente via XML"""
    if not os.path.exists(caminho_arquivo):
        return fallback if fallback is not None else {}
    try:
        ns = {"a": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
        with zipfile.ZipFile(caminho_arquivo) as arquivo_zip:
            shared_strings = []
            if "xl/sharedStrings.xml" in arquivo_zip.namelist():
                root = ET.fromstring(arquivo_zip.read("xl/sharedStrings.xml"))
                for si in root.findall("a:si", ns):
                    textos = [t.text or "" for t in si.iterfind(".//a:t", ns)]
                    shared_strings.append("".join(textos))
            sheet = ET.fromstring(arquivo_zip.read("xl/worksheets/sheet1.xml"))
            eletivas = {}
            professora_atual = None
            for row in sheet.findall(".//a:sheetData/a:row", ns):
                valores = {}
                for cell in row.findall("a:c", ns):
                    ref = cell.attrib.get("r", "")
                    col = "".join(ch for ch in ref if ch.isalpha())
                    tipo = cell.attrib.get("t")
                    valor = ""
                    v = cell.find("a:v", ns)
                    if v is not None and v.text:
                        valor = v.text
                    if tipo == "s" and valor.isdigit():
                        valor = shared_strings[int(valor)]
                    valores[col] = str(valor).strip()
                valor_a = valores.get("A", "")
                valor_b = valores.get("B", "")
                valor_c = valores.get("C", "")
                if valor_a and not valor_b and not valor_c:
                    professora_atual = valor_a
                    eletivas.setdefault(professora_atual, [])
                    continue
                if valor_a.upper() in ("Nº", "NO", "NUM"):
                    continue
                if valor_b.upper().startswith("NOME"):
                    continue
                if professora_atual and valor_b:
                    eletivas[professora_atual].append({"nome": valor_b, "serie": valor_c})
            eletivas = {prof: alunos for prof, alunos in eletivas.items() if alunos}
            return eletivas if eletivas else (fallback or {})
    except Exception as e:
        logger.error(f"Erro ao importar eletivas: {e}")
        return fallback if fallback is not None else {}

def carregar_tutoria_do_excel(caminho_arquivo: str, fallback: dict = None) -> dict:
    """Lê planilha XLSX de tutoria considerando cada aba como um tutor(a)."""
    if not caminho_arquivo or not os.path.exists(caminho_arquivo):
        return normalizar_base_tutoria(fallback if fallback is not None else {})
    try:
        ns = {
            "a": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
            "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
        }
        with zipfile.ZipFile(caminho_arquivo) as arquivo_zip:
            shared_strings = []
            if "xl/sharedStrings.xml" in arquivo_zip.namelist():
                root = ET.fromstring(arquivo_zip.read("xl/sharedStrings.xml"))
                for si in root.findall("a:si", ns):
                    textos = [t.text or "" for t in si.iterfind(".//a:t", ns)]
                    shared_strings.append("".join(textos))

            workbook = ET.fromstring(arquivo_zip.read("xl/workbook.xml"))
            rels = ET.fromstring(arquivo_zip.read("xl/_rels/workbook.xml.rels"))
            rel_map = {rel.attrib.get("Id", ""): rel.attrib.get("Target", "") for rel in rels}

            tutoria = {}
            for sheet in workbook.findall("a:sheets/a:sheet", ns):
                tutor_atual = str(sheet.attrib.get("name", "")).strip()
                rel_id = sheet.attrib.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id", "")
                target = rel_map.get(rel_id, "")
                if not tutor_atual or not target:
                    continue

                caminho_sheet = target.replace("\\", "/")
                if not caminho_sheet.startswith("xl/"):
                    caminho_sheet = f"xl/{caminho_sheet}"
                if caminho_sheet not in arquivo_zip.namelist():
                    continue

                root_sheet = ET.fromstring(arquivo_zip.read(caminho_sheet))
                registro_tutor = estrutura_tutoria_vazia(nome=tutor_atual)
                alunos_tutor = []

                for row in root_sheet.findall(".//a:sheetData/a:row", ns):
                    valores = {}
                    for cell in row.findall("a:c", ns):
                        ref = cell.attrib.get("r", "")
                        col = "".join(ch for ch in ref if ch.isalpha())
                        tipo = cell.attrib.get("t")
                        valor = ""
                        v = cell.find("a:v", ns)
                        if v is not None and v.text:
                            valor = v.text
                        if tipo == "s" and valor.isdigit():
                            valor = shared_strings[int(valor)]
                        valores[col] = str(valor).strip()

                    valor_a = str(valores.get("A", "")).strip()
                    valor_b = str(valores.get("B", "")).strip()
                    valor_c = str(valores.get("C", "")).strip()
                    valor_d = str(valores.get("D", "")).strip()
                    valor_e = str(valores.get("E", "")).strip()
                    valor_f = str(valores.get("F", "")).strip()

                    for valor_meta in [valor_a, valor_b, valor_c, valor_d, valor_e, valor_f]:
                        valor_meta = str(valor_meta).strip()
                        if not valor_meta:
                            continue
                        valor_norm = normalizar_texto(valor_meta)
                        if not registro_tutor["espaco"] and any(chave in valor_norm for chave in ("sala", "patio", "pátio", "leitura")) and not valor_norm.startswith("horario"):
                            registro_tutor["espaco"] = valor_meta
                        if not registro_tutor["horario"] and re.search(r"\d{1,2}:\d{2}", valor_meta):
                            registro_tutor["horario"] = valor_meta
                        if not registro_tutor["dia"] and any(dia in valor_norm for dia in DIAS_SEMANA_TUTORIA):
                            registro_tutor["dia"] = valor_meta

                    nome = ""
                    serie = ""

                    if valor_b and valor_c:
                        if not any(ch.isdigit() for ch in valor_b[:4]):
                            nome = valor_b
                            serie = valor_c
                    elif valor_a and valor_b:
                        if not valor_a.replace(".", "").isdigit():
                            nome = valor_a
                            serie = valor_b
                    elif valor_a:
                        combinado = re.match(r"^(.*?)(\d+\s*(?:º|°)?\s*[A-Za-z])$", valor_a)
                        if combinado:
                            nome = combinado.group(1).strip()
                            serie = combinado.group(2).strip()

                    nome_norm = normalizar_texto(nome)
                    if (
                        not nome
                        or nome_norm in {"nome", "nomes", "nome:", "numero", "numero nome:", "vagas", "cadastrados"}
                        or nome_norm.startswith("horario")
                        or nome_norm.startswith("sala")
                        or nome_norm.startswith("patio")
                    ):
                        continue

                    alunos_tutor.append({
                        "nome": nome.strip(),
                        "serie": formatar_turma_eletiva(serie.strip())
                    })

                if alunos_tutor:
                    registro_tutor["alunos"] = alunos_tutor
                    tutoria[tutor_atual] = registro_tutor

            return normalizar_base_tutoria(tutoria if tutoria else (fallback or {}))
    except Exception as e:
        logger.error(f"Erro ao importar tutoria: {e}")
        return normalizar_base_tutoria(fallback if fallback is not None else {})

def carregar_eletivas_supabase_segura(contexto: str = "carregar eletivas") -> pd.DataFrame:
    """Carrega eletivas do Supabase aceitando tabelas com ou sem RA."""
    if not SUPABASE_VALID:
        return pd.DataFrame()
    consultas = [
        "eletivas?select=professora,nome_aluno,serie,ra&limit=50000",
        "eletivas?select=professora,nome_aluno,serie&limit=50000",
        "eletivas?select=*&limit=50000",
    ]
    ultimo_erro = None
    for consulta in consultas:
        try:
            return _supabase_get_dataframe(consulta, contexto)
        except Exception as e:
            ultimo_erro = e
            continue
    logger.warning(f"Nao foi possivel carregar eletivas do Supabase: {ultimo_erro}")
    return pd.DataFrame()

def _extrair_ra_de_row_ou_item(obj) -> str:
    aliases = ["ra", "RA", "nr_ra", "NR RA", "nrra", "codigo_ra", "Código RA"]
    for alias in aliases:
        try:
            valor = obj.get(alias, "")
        except Exception:
            valor = ""
        ra = "".join(ch for ch in str(valor or "") if ch.isdigit())
        if ra:
            return ra
    return ""

def converter_eletivas_para_registros(eletivas_dict: dict, origem: str = "excel") -> list:
    registros = []
    for professora, alunos in (eletivas_dict or {}).items():
        for item in alunos or []:
            nome = str(item.get("nome", "")).strip()
            serie = formatar_turma_eletiva(item.get("serie", ""))
            ra = _extrair_ra_de_row_ou_item(item)
            if not professora or not nome:
                continue
            registro = {
                "professora": str(professora).strip(),
                "nome_aluno": nome,
                "serie": serie,
                "origem": origem,
            }
            if ra:
                registro["ra"] = ra
            registros.append(registro)
    return registros

def converter_eletivas_supabase_para_dict(df_eletivas: pd.DataFrame) -> dict:
    if df_eletivas is None or df_eletivas.empty:
        return {}
    eletivas = {}
    for _, row in df_eletivas.iterrows():
        professora = str(row.get("professora", "")).strip()
        nome_aluno = str(row.get("nome_aluno", row.get("nome", ""))).strip()
        serie = formatar_turma_eletiva(str(row.get("serie", row.get("turma", ""))).strip())
        ra = _extrair_ra_de_row_ou_item(row)
        if not professora or not nome_aluno:
            continue
        item = {"nome": nome_aluno, "serie": serie}
        if ra:
            item["ra"] = ra
        eletivas.setdefault(professora, []).append(item)
    return eletivas

def converter_tutoria_para_registros(tutoria_dict: dict, origem: str = "excel") -> list:
    registros = []
    for tutor, dados in normalizar_base_tutoria(tutoria_dict).items():
        for item in dados.get("alunos", []):
            serie_fmt = formatar_turma_eletiva(item.get("serie", ""))
            registros.append({
                "professora": tutor,
                "nome_aluno": item.get("nome", ""),
                "serie": serie_fmt,
                "ra": "".join(ch for ch in str(item.get("ra", "")) if ch.isdigit()),
                "origem": origem,
                "tipo": normalizar_perfil_tutoria(dados.get("tipo", "Professor(a)")),
                "espaco": str(dados.get("espaco", "")).strip(),
                "horario": str(dados.get("horario", "")).strip(),
                "dia": str(dados.get("dia", "")).strip(),
                "turno": classificar_turno_tutoria(serie_fmt),
            })
    return registros


def converter_tutoria_responsaveis_para_registros(tutoria_dict: dict) -> list:
    registros = []
    for tutor, dados in normalizar_base_tutoria(tutoria_dict).items():
        alunos = dados.get("alunos", []) or []
        turnos = sorted({
            classificar_turno_tutoria(item.get("serie", ""))
            for item in alunos
            if classificar_turno_tutoria(item.get("serie", "")) != "Sem turno definido"
        })
        registros.append({
            "responsavel": tutor,
            "perfil": normalizar_perfil_tutoria(dados.get("tipo", "Professor(a)")),
            "espaco": str(dados.get("espaco", "") or espaco_oficial_por_tutor(tutor)).strip(),
            "horario": str(dados.get("horario", "") or TUTORIA_HORARIO_PADRAO_TURNO1).strip(),
            "dia": str(dados.get("dia", "") or TUTORIA_DIA_PADRAO_TURNO1).strip(),
            "turno": ", ".join(turnos),
            "ativo": True,
        })
    return registros


def sincronizar_tutoria_responsaveis_supabase(tutoria_dict: dict) -> tuple[bool, str]:
    registros = converter_tutoria_responsaveis_para_registros(tutoria_dict)
    if not SUPABASE_VALID or not registros:
        return False, "Supabase indisponível ou sem registros."
    try:
        _supabase_request(
            "POST",
            "tutoria_responsaveis?on_conflict=responsavel",
            json=registros,
            headers={"Prefer": "resolution=merge-duplicates,return=representation"},
        )
        return True, "Responsáveis da tutoria sincronizados no Supabase."
    except Exception as e:
        return False, mensagem_erro_tutoria_supabase(e)



def _chave_registro_tutoria_supabase(reg: dict) -> tuple:
    return (
        normalizar_texto(reg.get("professora", "")),
        normalizar_texto(reg.get("nome_aluno", "")),
        turma_para_comparacao(reg.get("serie", "")),
        "".join(ch for ch in str(reg.get("ra", "")) if ch.isdigit()),
    )


def _valor_json_seguro_tutoria(valor):
    """Converte valores do pandas/Streamlit para JSON aceito pelo Supabase."""
    try:
        if pd.isna(valor):
            return ""
    except Exception:
        pass
    if valor is None:
        return ""
    if isinstance(valor, (list, dict, tuple, set)):
        return json.dumps(valor, ensure_ascii=False)
    return str(valor).strip()


def _filtrar_registros_tutoria(registros: list[dict], colunas: list[str]) -> list[dict]:
    filtrados = []
    for reg in registros or []:
        item = {}
        for col in colunas:
            if col in reg:
                item[col] = _valor_json_seguro_tutoria(reg.get(col))
        if item.get("professora") and item.get("nome_aluno"):
            filtrados.append(item)
    return filtrados


def _post_tutoria_lote_com_fallback(registros_lote: list[dict]):
    """Salva vínculos de Tutoria tolerando diferenças de colunas na tabela do Supabase.

    O erro 400 em /rest/v1/tutoria geralmente acontece quando o payload tem
    alguma coluna que não existe no banco atual, ou quando há valor não aceito
    pelo PostgREST. Esta função tenta primeiro o formato completo e depois
    formatos menores, sem perder os dados essenciais.
    """
    tentativas_colunas = [
        ["professora", "nome_aluno", "serie", "ra", "origem", "tipo", "espaco", "horario", "dia", "turno"],
        ["professora", "nome_aluno", "serie", "ra", "tipo", "espaco", "horario", "dia"],
        ["professora", "nome_aluno", "serie", "ra"],
        ["professora", "nome_aluno", "serie"],
    ]
    ultimo_erro = None
    for colunas in tentativas_colunas:
        payload = _filtrar_registros_tutoria(registros_lote, colunas)
        if not payload:
            continue
        try:
            _supabase_request(
                "POST",
                "tutoria",
                json=payload,
                headers={"Prefer": "return=minimal"},
            )
            return True, f"salvo com colunas: {', '.join(colunas)}"
        except Exception as e:
            ultimo_erro = e
            logger.warning(f"Falha ao salvar lote de tutoria com colunas {colunas}: {e}")
            continue
    if ultimo_erro:
        raise ultimo_erro
    return False, "sem payload válido"


def _limpar_cache_tutoria_apos_mutacao():
    """Limpa caches para a tela refletir inclusões/edições/exclusões imediatamente."""
    chaves = [
        "tutoria_validacao_ultimo",
        "tutoria_bloqueados_ultimo",
        "tutoria_responsaveis_sync_warning",
        "df_tutoria_supabase",
    ]
    for chave in chaves:
        try:
            st.session_state.pop(chave, None)
        except Exception:
            pass
    try:
        _limpar_cache_pos_mutacao()
    except Exception:
        pass


def _excluir_registro_tutoria_supabase(tutor_nome: str, nome_aluno: str = "", serie: str = "", ra: str = "") -> tuple[bool, str]:
    """Exclui vínculo de tutoria no Supabase de forma direcionada."""
    if not SUPABASE_VALID:
        return True, "Supabase indisponível; exclusão aplicada apenas na sessão/cache local."
    tutor = str(tutor_nome or "").strip()
    nome = str(nome_aluno or "").strip()
    turma = formatar_turma_eletiva(str(serie or "").strip())
    ra_limpo = "".join(ch for ch in str(ra or "") if ch.isdigit())
    if not tutor or (not nome and not ra_limpo):
        return False, "Informe tutor e estudante para excluir."
    try:
        tutor_q = requests.utils.quote(tutor, safe="")
        if ra_limpo:
            ra_q = requests.utils.quote(ra_limpo, safe="")
            try:
                _supabase_request("DELETE", f"tutoria?professora=eq.{tutor_q}&ra=eq.{ra_q}")
                _limpar_cache_tutoria_apos_mutacao()
                return True, "Vínculo excluído no Supabase pelo RA."
            except Exception as e_ra:
                logger.warning(f"Falha ao excluir tutoria por RA; tentando por nome/turma: {e_ra}")
        nome_q = requests.utils.quote(nome, safe="")
        turma_q = requests.utils.quote(turma, safe="")
        _supabase_request("DELETE", f"tutoria?professora=eq.{tutor_q}&nome_aluno=eq.{nome_q}&serie=eq.{turma_q}")
        _limpar_cache_tutoria_apos_mutacao()
        return True, "Vínculo excluído no Supabase por professor, nome e turma."
    except Exception as e:
        return False, mensagem_erro_tutoria_supabase(e)


def _excluir_lista_tutoria_supabase(tutor_nome: str) -> tuple[bool, str]:
    """Exclui todos os vínculos de tutoria de um único responsável, sem mexer nos demais."""
    if not SUPABASE_VALID:
        return True, "Supabase indisponível; limpeza aplicada apenas na sessão/cache local."
    tutor = str(tutor_nome or "").strip()
    if not tutor:
        return False, "Informe o responsável para excluir a lista."
    try:
        tutor_q = requests.utils.quote(tutor, safe="")
        _supabase_request("DELETE", f"tutoria?professora=eq.{tutor_q}")
        _limpar_cache_tutoria_apos_mutacao()
        return True, "Lista do responsável excluída no Supabase."
    except Exception as e:
        return False, mensagem_erro_tutoria_supabase(e)


def sincronizar_tutoria_listas_supabase(tutoria_dict: dict) -> tuple[bool, str]:
    """Salva em lote as listas de tutoria SEM apagar vínculos existentes.

    Regra de segurança: esta rotina é aditiva/mesclada. Ela nunca executa
    DELETE em lote. Se um estudante foi removido da tela, ele permanece no
    Supabase até uma rotina de arquivamento seguro existir.
    """
    if not SUPABASE_VALID:
        return False, "Supabase não configurado."

    base = normalizar_base_tutoria(tutoria_dict)
    registros = converter_tutoria_para_registros(base, origem="app_lote_seguro")

    if not registros:
        return False, "Não há estudantes vinculados para salvar. Nada foi apagado do Supabase."

    try:
        registros_online = []
        try:
            df_online = _supabase_get_dataframe("tutoria?select=professora,nome_aluno,serie,ra&limit=50000", "carregar vínculos de tutoria")
            if isinstance(df_online, pd.DataFrame) and not df_online.empty:
                registros_online = df_online.to_dict("records")
        except Exception:
            registros_online = []

        chaves_online = {_chave_registro_tutoria_supabase(r) for r in registros_online}
        novos = []
        vistos_lote = set()
        for reg in registros:
            chave = _chave_registro_tutoria_supabase(reg)
            if not chave[0] or not chave[1]:
                continue
            if chave in chaves_online or chave in vistos_lote:
                continue
            novos.append(reg)
            vistos_lote.add(chave)

        detalhes_salvamento = []
        if novos:
            tamanho_lote = 200
            for inicio in range(0, len(novos), tamanho_lote):
                ok_lote, detalhe_lote = _post_tutoria_lote_com_fallback(novos[inicio:inicio + tamanho_lote])
                if detalhe_lote:
                    detalhes_salvamento.append(detalhe_lote)

        ok_resp, msg_resp = sincronizar_tutoria_responsaveis_supabase(base)
        try:
            _limpar_cache_supabase_completo()
        except Exception:
            pass
        complemento = f" Responsáveis: {msg_resp}" if msg_resp else ""
        detalhe = f" Formato usado: {' | '.join(detalhes_salvamento)}." if detalhes_salvamento else ""
        return True, f"{len(novos)} vínculo(s) novo(s) salvos; {len(registros) - len(novos)} já existiam e foram preservados. Nenhum vínculo foi apagado." + detalhe + complemento
    except Exception as e:
        return False, mensagem_erro_tutoria_supabase(e)

def converter_tutoria_supabase_para_dict(df_tutoria: pd.DataFrame) -> dict:
    if df_tutoria.empty:
        return {}
    tutoria = {}
    aliases_tutor = ["professora", "professor", "responsavel", "responsável", "tutor", "nome_tutor", "nome_professor"]
    aliases_aluno = ["nome_aluno", "aluno", "estudante", "nome_estudante", "nome"]
    aliases_serie = ["serie", "série", "turma", "ano_serie", "ano_série"]
    aliases_tipo = ["tipo", "perfil", "cargo", "funcao", "função"]
    aliases_espaco = ["espaco", "espaço", "espaco_usado", "espaço_usado", "sala", "ambiente", "local"]
    aliases_horario = ["horario", "horário", "hora", "periodo", "período"]
    aliases_dia = ["dia", "dia_semana", "dia_da_semana", "semana"]
    aliases_turno = ["turno", "periodo_turno", "período_turno"]
    for _, row in df_tutoria.iterrows():
        tutor = _valor_primeiro_campo(row, aliases_tutor)
        nome_aluno = _valor_primeiro_campo(row, aliases_aluno)
        serie = formatar_turma_eletiva(_valor_primeiro_campo(row, aliases_serie))
        if not tutor:
            continue
        tutoria.setdefault(tutor, estrutura_tutoria_vazia(nome=tutor))
        tipo = normalizar_perfil_tutoria(_valor_primeiro_campo(row, aliases_tipo) or "Professor(a)")
        espaco = _valor_primeiro_campo(row, aliases_espaco)
        horario = _valor_primeiro_campo(row, aliases_horario)
        dia = _valor_primeiro_campo(row, aliases_dia)
        turno = _valor_primeiro_campo(row, aliases_turno)
        if tipo:
            tutoria[tutor]["tipo"] = tipo
        if espaco:
            tutoria[tutor]["espaco"] = espaco
        if horario:
            tutoria[tutor]["horario"] = horario
        if dia:
            tutoria[tutor]["dia"] = dia
        if nome_aluno:
            item = {"nome": nome_aluno, "serie": serie}
            ra = _valor_primeiro_campo(row, ["ra", "RA", "registro_aluno"])
            if ra:
                item["ra"] = "".join(ch for ch in str(ra) if ch.isdigit())
            tutoria[tutor]["alunos"].append(item)
        if turno:
            tutoria[tutor]["turno"] = turno
    return normalizar_base_tutoria(tutoria)

def carregar_tutoria_supabase_segura(motivo: str = "carregar tutoria") -> pd.DataFrame:
    """Carrega vínculos da Tutoria sem deixar a tela zerar por erro de coluna.

    Algumas versões da tabela public.tutoria não possuem todas as colunas
    usadas pelo app (por exemplo origem, tipo, espaço, horário). Quando o
    select pede uma coluna inexistente, o Supabase retorna 400 e o app acabava
    tratando como tabela vazia. Esta função tenta consultas em cascata e só
    devolve vazio quando realmente não conseguiu carregar nenhum formato.
    """
    if not SUPABASE_VALID:
        return pd.DataFrame()
    consultas = [
        "tutoria?select=professora,nome_aluno,serie,ra,tipo,espaco,horario,dia,turno,origem&limit=50000",
        "tutoria?select=professora,nome_aluno,serie,ra,tipo,espaco,horario,dia,turno&limit=50000",
        "tutoria?select=professora,nome_aluno,serie,ra&limit=50000",
        "tutoria?select=*&limit=50000",
    ]
    ultimo_erro = None
    for consulta in consultas:
        try:
            df = _supabase_get_dataframe(consulta, motivo)
            if isinstance(df, pd.DataFrame):
                if not df.empty:
                    return df
                # guarda o vazio, mas continua tentando select=* caso o formato
                # anterior tenha sido válido e a tabela realmente esteja vazia.
                ultimo_vazio = df
        except Exception as e:
            ultimo_erro = e
            logger.warning(f"Falha ao carregar tutoria com consulta {consulta}: {e}")
    if ultimo_erro is not None:
        st.session_state["tutoria_responsaveis_sync_warning"] = (
            "Não consegui carregar os vínculos da Tutoria no primeiro formato. "
            "Usei as proteções de cache/backup para não apagar estudantes."
        )
    return pd.DataFrame()


def carregar_tutoria_referencias_supabase_segura() -> dict:
    """Carrega metadados de responsáveis se a tabela existir; nunca apaga vínculos."""
    if not SUPABASE_VALID:
        return {}
    consultas = [
        "tutoria_responsaveis?select=responsavel,perfil,espaco,horario,dia,turno&limit=50000",
        "tutoria_responsaveis?select=*&limit=50000",
    ]
    for consulta in consultas:
        try:
            df = _supabase_get_dataframe(consulta, "carregar responsáveis da tutoria")
            if isinstance(df, pd.DataFrame) and not df.empty:
                return converter_tutoria_supabase_para_dict(df)
        except Exception as e:
            logger.warning(f"Falha ao carregar responsáveis da tutoria: {e}")
    return {}


def _extrair_dict_tutoria_de_backup_objeto(obj) -> dict:
    """Tenta reconhecer uma base de tutoria dentro de backups JSON variados.

    Aceita tanto o formato já normalizado {tutor: {alunos: [...]}} quanto
    listas de registros vindas da tabela public.tutoria.
    """
    try:
        if obj is None:
            return {}
        if isinstance(obj, str):
            texto = obj.strip()
            if not texto or texto.lower() in ("none", "null", "nan"):
                return {}
            try:
                obj = json.loads(texto)
            except Exception:
                return {}
        if isinstance(obj, list):
            if not obj:
                return {}
            if all(isinstance(x, dict) for x in obj):
                return converter_tutoria_supabase_para_dict(pd.DataFrame(obj))
            return {}
        if isinstance(obj, dict):
            # Formato direto: {"Tutor": {"alunos": [...]}}
            direto = normalizar_base_tutoria(obj)
            if total_estudantes_tutoria(direto) > 0:
                return direto
            # Formatos comuns: {"tutoria": {...}}, {"dados": {...}}, {"backup": {...}}
            for chave in ["tutoria", "TUTORIA", "dados", "data", "backup", "conteudo", "json", "payload", "registros"]:
                if chave in obj:
                    convertido = _extrair_dict_tutoria_de_backup_objeto(obj.get(chave))
                    if total_estudantes_tutoria(convertido) > 0:
                        return convertido
            # Se o dicionário for uma linha de tabela, tenta cada coluna.
            for valor in obj.values():
                convertido = _extrair_dict_tutoria_de_backup_objeto(valor)
                if total_estudantes_tutoria(convertido) > 0:
                    return convertido
    except Exception as e:
        logger.warning(f"Falha ao interpretar backup JSON da tutoria: {e}")
    return {}


def carregar_tutoria_backups_json_supabase_segura() -> dict:
    """Recupera vínculos da tabela public.tutoria_backups_json, quando existir.

    Essa tabela apareceu no seu projeto e serve como rede de segurança. A rotina
    é somente leitura e escolhe o backup com maior quantidade de tutorados.
    """
    if not SUPABASE_VALID:
        return {}
    consultas = [
        "tutoria_backups_json?select=*&order=created_at.desc&limit=30",
        "tutoria_backups_json?select=*&order=id.desc&limit=30",
        "tutoria_backups_json?select=*&limit=30",
    ]
    melhor = {}
    for consulta in consultas:
        try:
            df = _supabase_get_dataframe(consulta, "carregar backups JSON da tutoria")
            if not isinstance(df, pd.DataFrame) or df.empty:
                continue
            for _, row in df.iterrows():
                convertido = _extrair_dict_tutoria_de_backup_objeto(row.to_dict())
                if total_estudantes_tutoria(convertido) > total_estudantes_tutoria(melhor):
                    melhor = convertido
            if total_estudantes_tutoria(melhor) > 0:
                return melhor
        except Exception as e:
            logger.warning(f"Não consegui carregar tutoria_backups_json com {consulta}: {e}")
    return melhor


def salvar_tutoria_backup_json_supabase_seguro(tutoria_dict: dict, origem: str = "app"):
    """Cria backup JSON no Supabase sem interferir na tabela principal.

    É tolerante a schema: tenta campos comuns e ignora se a tabela não aceitar.
    """
    if not SUPABASE_VALID:
        return
    base = normalizar_base_tutoria(tutoria_dict or {})
    if total_estudantes_tutoria(base) == 0:
        return
    payloads = [
        {"origem": origem, "dados": base},
        {"origem": origem, "tutoria": base},
        {"conteudo": json.dumps(base, ensure_ascii=False), "origem": origem},
        {"json": base},
    ]
    for payload in payloads:
        try:
            _supabase_request("POST", "tutoria_backups_json", json=payload)
            return
        except Exception:
            continue


def montar_dataframe_eletiva(nome_professora: str, df_alunos: pd.DataFrame, eletivas_dict: dict) -> pd.DataFrame:
    registros = []
    alunos_db = df_alunos.copy()
    # Todas as contagens e vinculações de Eletiva/Tutoria devem considerar apenas estudantes ativos.
    # Isso evita que transferidos/inativos entrem nos cards, impressões e buscas.
    try:
        if not alunos_db.empty:
            alunos_db = alunos_db[alunos_db.apply(estudante_ativo, axis=1)].copy()
    except Exception:
        pass
    nome_coluna = None
    for c in alunos_db.columns:
        if c.lower() in ("nome", "nome do aluno", "aluno"):
            nome_coluna = c
            break
    if nome_coluna:
        alunos_db["nome_norm"] = alunos_db[nome_coluna].apply(normalizar_texto)
    else:
        alunos_db["nome_norm"] = ""
    if "ra" in alunos_db.columns:
        alunos_db["ra_norm"] = alunos_db["ra"].astype(str).apply(lambda x: "".join(ch for ch in x if ch.isdigit()))
    else:
        alunos_db["ra_norm"] = ""
    if "turma" in alunos_db.columns:
        alunos_db["turma_norm"] = alunos_db["turma"].astype(str).apply(normalizar_texto)
    else:
        alunos_db["turma_norm"] = ""

    for item in eletivas_dict.get(nome_professora, []):
        nome_original = item.get("nome", "")
        serie_original = formatar_turma_eletiva(item.get("serie", ""))
        ra_original = "".join(ch for ch in str(item.get("ra", "")) if ch.isdigit())
        nome_norm_excel = normalizar_texto(nome_original)
        melhor_match = None

        # 1) Prioriza match por RA quando disponível
        if ra_original:
            match_ra = alunos_db[alunos_db["ra_norm"] == ra_original]
            if not match_ra.empty:
                melhor_match = match_ra.iloc[0]

        # 2) Match exato por nome (evita pegar irmã/irmão por similaridade)
        if melhor_match is None and nome_norm_excel:
            exatos = alunos_db[alunos_db["nome_norm"] == nome_norm_excel]
            if not exatos.empty:
                exatos_serie = exatos[exatos["turma_norm"].apply(lambda t: serie_compativel_turma(serie_original, t))]
                melhor_match = (exatos_serie.iloc[0] if not exatos_serie.empty else exatos.iloc[0])

        # 3) Fuzzy apenas como fallback, com regra de primeiro nome + série
        if melhor_match is None and nome_norm_excel:
            primeiro_nome = nome_norm_excel.split()[0] if nome_norm_excel.split() else ""
            melhor_score = 0.0
            for _, aluno in alunos_db.iterrows():
                nome_sis = aluno.get("nome_norm", "")
                if not nome_sis:
                    continue
                if primeiro_nome and not nome_sis.startswith(primeiro_nome):
                    continue
                if not serie_compativel_turma(serie_original, aluno.get("turma_norm", "")):
                    continue
                score = SequenceMatcher(None, nome_norm_excel, nome_sis).ratio()
                if score > melhor_score:
                    melhor_score = score
                    melhor_match = aluno
            if melhor_score < 0.92:
                melhor_match = None

        if melhor_match is not None:
            turma_final = str(melhor_match.get("turma", "")).strip() or serie_original
            classif_final = classificar_turma_sistema(turma_final)
            registros.append({
                "Professor(a)": nome_professora,
                "Nome": nome_original,
                "Turma": turma_final,
                "Ciclo": classif_final["ciclo"],
                "Turno": classif_final["turno"],
                "Aluno Cadastrado": melhor_match.get("nome", ""),
                "RA": melhor_match.get("ra", ""),
                "Turma no Sistema": melhor_match.get("turma", ""),
                "Situação": melhor_match.get("situacao", ""),
                "Status": "Encontrado",
            })
        else:
            classif_final = classificar_turma_sistema(serie_original)
            registros.append({
                "Professor(a)": nome_professora,
                "Nome": nome_original,
                "Turma": serie_original,
                "Ciclo": classif_final["ciclo"],
                "Turno": classif_final["turno"],
                "Aluno Cadastrado": "",
                "RA": "",
                "Turma no Sistema": "",
                "Situação": "",
                "Status": "Não encontrado",
            })
    df_final = pd.DataFrame(registros)
    if not df_final.empty:
        colunas_ordenacao = [c for c in ["Turma", "Nome"] if c in df_final.columns]
        if colunas_ordenacao:
            df_final = df_final.sort_values(colunas_ordenacao, kind="stable").reset_index(drop=True)
    return df_final

def montar_dataframe_tutoria(nome_tutor: str, df_alunos: pd.DataFrame, tutoria_dict: dict) -> pd.DataFrame:
    registro_tutor = obter_registro_tutoria(tutoria_dict, nome_tutor)
    df_tutoria = montar_dataframe_eletiva(
        nome_tutor,
        df_alunos,
        {nome_tutor: registro_tutor.get("alunos", [])}
    )
    if df_tutoria.empty:
        return df_tutoria
    df_tutoria["Espaço"] = registro_tutor.get("espaco", "")
    df_tutoria["Horário"] = registro_tutor.get("horario", "")
    df_tutoria["Dia"] = registro_tutor.get("dia", "")
    df_tutoria["Perfil"] = registro_tutor.get("tipo", "Professor(a)")
    # Na página de Tutoria, exibir e contar somente estudantes oficialmente ativos.
    # Linhas com Não Comparecimento, Remanejamento, Troca, Transferido etc. ficam ocultas.
    if "Situação" in df_tutoria.columns:
        df_tutoria = df_tutoria[df_tutoria["Situação"].apply(lambda v: normalizar_texto(v) in {"ATIVO", "ATIVA"})].copy()
    if "Status" in df_tutoria.columns:
        df_tutoria = df_tutoria[df_tutoria["Status"].astype(str).str.strip().eq("Encontrado")].copy()
    if "Nome" in df_tutoria.columns:
        df_tutoria = df_tutoria.sort_values(["Nome"], kind="stable").reset_index(drop=True)
    return df_tutoria

def _indice_alunos_para_atualizar_turmas(df_alunos: pd.DataFrame) -> tuple[dict, dict]:
    """Monta índices por RA e por nome para atualizar turmas nas listas vinculadas."""
    base = preparar_base_alunos_ativos_tutoria(df_alunos)
    por_ra = {}
    por_nome = {}
    if base.empty:
        return por_ra, por_nome

    for _, aluno in base.iterrows():
        nome = str(aluno.get("nome", "")).strip()
        turma = formatar_turma_eletiva(str(aluno.get("turma", "")).strip())
        ra = "".join(ch for ch in str(aluno.get("ra", "")) if ch.isdigit())
        situacao = str(aluno.get("situacao", "Ativo") or "Ativo").strip()
        registro = {"nome": nome, "serie": turma, "ra": ra, "situacao": situacao}
        if ra:
            por_ra[ra] = registro
        nome_norm = normalizar_texto(nome)
        if nome_norm and nome_norm not in por_nome:
            por_nome[nome_norm] = registro
    return por_ra, por_nome

def _atualizar_item_lista_com_base(item: dict, por_ra: dict, por_nome: dict) -> bool:
    """Atualiza nome/turma/RA de um item de eletiva/tutoria a partir da base oficial."""
    if not isinstance(item, dict):
        return False
    ra = "".join(ch for ch in str(item.get("ra", "")) if ch.isdigit())
    nome_norm = normalizar_texto(item.get("nome", ""))
    aluno_base = por_ra.get(ra) if ra else None
    if aluno_base is None and nome_norm:
        aluno_base = por_nome.get(nome_norm)
    if aluno_base is None:
        return False

    mudou = False
    turma_atual = formatar_turma_eletiva(str(item.get("serie", "")).strip())
    turma_base = formatar_turma_eletiva(aluno_base.get("serie", ""))
    if turma_base and turma_para_comparacao(turma_atual) != turma_para_comparacao(turma_base):
        item["serie"] = turma_base
        mudou = True
    if aluno_base.get("ra") and str(item.get("ra", "")).strip() != aluno_base.get("ra"):
        item["ra"] = aluno_base.get("ra")
        mudou = True
    if aluno_base.get("nome") and normalizar_texto(item.get("nome", "")) == nome_norm and str(item.get("nome", "")).strip() != aluno_base.get("nome"):
        item["nome"] = aluno_base.get("nome")
        mudou = True
    if aluno_base.get("situacao") and str(item.get("situacao", "") or "").strip() != aluno_base.get("situacao"):
        item["situacao"] = aluno_base.get("situacao")
        mudou = True
    return mudou

def sincronizar_turmas_listas_com_base(df_alunos_atualizado: pd.DataFrame, origem: str = "base_alunos") -> dict:
    """
    Mantém Eletiva e Tutoria com a turma atual da base de alunos.
    Quando a lista oficial muda a sala do estudante, a sala refletida nas listas também é atualizada.
    """
    por_ra, por_nome = _indice_alunos_para_atualizar_turmas(df_alunos_atualizado)
    stats = {"eletivas": 0, "tutoria": 0}
    if not por_ra and not por_nome:
        return stats

    eletivas_base = st.session_state.get("ELETIVAS") or ELETIVAS
    for professora, alunos in (eletivas_base or {}).items():
        for item in alunos or []:
            if _atualizar_item_lista_com_base(item, por_ra, por_nome):
                stats["eletivas"] += 1
    st.session_state.ELETIVAS = eletivas_base

    tutoria_base = normalizar_base_tutoria(st.session_state.get("TUTORIA", TUTORIA))
    for _, dados in tutoria_base.items():
        for item in dados.get("alunos", []) or []:
            if _atualizar_item_lista_com_base(item, por_ra, por_nome):
                stats["tutoria"] += 1
    st.session_state.TUTORIA = normalizar_base_tutoria(tutoria_base)
    if stats["tutoria"]:
        salvar_tutoria_local(st.session_state.TUTORIA)

    if SUPABASE_VALID:
        try:
            if stats["eletivas"]:
                registros_eletivas = converter_eletivas_para_registros(st.session_state.ELETIVAS, origem=f"{origem}_turma_atualizada")
                _supabase_request("DELETE", "eletivas?id=not.is.null")
                if registros_eletivas:
                    _supabase_request("POST", "eletivas", json=registros_eletivas)
                st.session_state.FONTE_ELETIVAS = "supabase"
            if stats["tutoria"]:
                # Nunca apagar todos os vínculos da tutoria para regravar.
                # Essa rotina apenas acrescenta/mescla vínculos, preservando o que já existe.
                salvar_tutoria_backup_json_supabase_seguro(st.session_state.TUTORIA, origem=f"{origem}_antes_sync_turmas")
                ok_tut, msg_tut = sincronizar_tutoria_listas_supabase(st.session_state.TUTORIA)
                if ok_tut:
                    st.session_state.FONTE_TUTORIA = "supabase"
                else:
                    logger.warning(f"Sincronização segura da tutoria não concluída: {msg_tut}")
        except Exception as e:
            logger.warning(f"Não foi possível persistir a atualização de turmas das listas: {e}")

    return stats

ELETIVAS_EXCEL = carregar_eletivas_do_excel(ELETIVAS_ARQUIVO, fallback=ELETIVAS)
TUTORIA_EXCEL = carregar_tutoria_do_excel(TUTORIA_ARQUIVO, fallback={})
