def _normalizar_chave_estudante(valor: str) -> str:
    texto = unicodedata.normalize("NFKD", str(valor or "")).encode("ASCII", "ignore").decode("ASCII")
    texto = re.sub(r"[^A-Z0-9]+", " ", texto.upper()).strip()
    return re.sub(r"\s+", " ", texto)


def _normalizar_ra_estudante(valor) -> str:
    return re.sub(r"\D", "", str(valor or ""))


def _bimestre_para_coluna_caderno(valor: str) -> str:
    n = normalizar_texto(valor)
    if "1" in n:
        return "1º BIM"
    if "2" in n:
        return "2º BIM"
    if "3" in n:
        return "3º BIM"
    if "4" in n:
        return "4º BIM"
    return "1º BIM"


def _componente_para_disciplina_caderno(comp: str) -> str:
    n = normalizar_texto(comp)
    n = n.replace("LINGUA", "LÍNGUA")
    mapa = {
        "MAT": "MATEMÁTICA",
        "MATEMATICA": "MATEMÁTICA",
        "PORT": "LÍNGUA PORTUGUESA",
        "LP": "LÍNGUA PORTUGUESA",
        "LINGUA PORTUGUESA": "LÍNGUA PORTUGUESA",
        "LÍNGUA PORTUGUESA": "LÍNGUA PORTUGUESA",
        "ING": "LÍNGUA INGLESA",
        "INGLES": "LÍNGUA INGLESA",
        "LÍNGUA INGLESA": "LÍNGUA INGLESA",
        "HIST": "HISTÓRIA",
        "HISTORIA": "HISTÓRIA",
        "GEO": "GEOGRAFIA",
        "GEOGRAFIA": "GEOGRAFIA",
        "CIE": "CIÊNCIA",
        "CIENCIAS": "CIÊNCIA",
        "CIENCIA": "CIÊNCIA",
        "ARTE": "ARTE",
        "ED FISICA": "EDUCAÇÃO FÍSICA",
        "EDUCACAO FISICA": "EDUCAÇÃO FÍSICA",
        "EDUCAÇÃO FÍSICA": "EDUCAÇÃO FÍSICA",
        "FIN": "EDUCAÇÃO FINANCEIRA",
        "EDUCACAO FINANCEIRA": "EDUCAÇÃO FINANCEIRA",
        "EDUCAÇÃO FINANCEIRA": "EDUCAÇÃO FINANCEIRA",
        "TEC": "TECNOLOGIA E INOVAÇÃO",
        "TECNOLOGIA": "TECNOLOGIA E INOVAÇÃO",
        "TECNOLOGIA E INOVACAO": "TECNOLOGIA E INOVAÇÃO",
        "PROJETO DE VIDA": "PROJETO DE VIDA",
        "PV": "PROJETO DE VIDA",
        "ELETIVA": "ELETIVA",
        "REDAÇÃO E LEITURA": "REDAÇÃO E LEITURA",
        "REDACAO E LEITURA": "REDAÇÃO E LEITURA",
        "ORIENTACAO DE ESTUDOS LINGUA PORTUGUESA": "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA",
        "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA": "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA",
        "ORIENTACAO DE ESTUDO LINGUA PORTUGUESA": "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA",
        "ORIENTAÇÃO DE ESTUDO LÍNGUA PORTUGUESA": "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA",
        "OE LP": "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA",
        "ORIENTACAO DE ESTUDOS MATEMATICA": "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA",
        "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA": "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA",
        "ORIENTACAO DE ESTUDO MATEMATICA": "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA",
        "ORIENTAÇÃO DE ESTUDO MATEMÁTICA": "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA",
        "OE MAT": "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA",
    }
    if n in mapa:
        return mapa[n]
    if "ORIENT" in n and "PORT" in n:
        return "ORIENTAÇÃO DE ESTUDOS LÍNGUA PORTUGUESA"
    if "ORIENT" in n and "MAT" in n:
        return "ORIENTAÇÃO DE ESTUDOS MATEMÁTICA"
    if "REDAC" in n or ("LEIT" in n and "RED" in n):
        return "REDAÇÃO E LEITURA"
    for chave, valor in mapa.items():
        if chave in n or n in chave:
            return valor
    return str(comp or "").strip().upper()


def _dataframe_seguro_carregador(nome: str) -> pd.DataFrame:
    try:
        if nome == "prova_paulista":
            return _carregar_prova_paulista_local()
        if nome == "mapao":
            return _carregar_mapao_local()
        if nome == "ocorrencias":
            try:
                return carregar_ocorrencias()
            except Exception:
                return globals().get("df_ocorrencias", pd.DataFrame())
    except Exception:
        return pd.DataFrame()
    return pd.DataFrame()


def _filtrar_aluno_df(df: pd.DataFrame, nome: str, ra: str = "", turma: str = "") -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame()
    base = df.copy()
    ra_norm = _normalizar_ra_estudante(ra)
    nome_norm = _normalizar_chave_estudante(nome)
    turma_norm = normalizar_texto(turma)
    mask = pd.Series(False, index=base.index)
    for col in ["RA", "ra", "NR RA", "nr_ra"]:
        if col in base.columns and ra_norm:
            mask = mask | (base[col].astype(str).apply(_normalizar_ra_estudante) == ra_norm)
    for col in ["Estudante", "estudante", "aluno", "Aluno", "nome", "Nome"]:
        if col in base.columns and nome_norm:
            mask = mask | (base[col].astype(str).apply(_normalizar_chave_estudante) == nome_norm)
    filtrado = base[mask].copy()
    if turma_norm and not filtrado.empty:
        for col in ["Turma", "turma"]:
            if col in filtrado.columns:
                filtrado_turma = filtrado[filtrado[col].astype(str).apply(normalizar_texto) == turma_norm].copy()
                if not filtrado_turma.empty:
                    return filtrado_turma
    return filtrado


def _resumo_prova_paulista_aluno(nome: str, ra: str = "", turma: str = "") -> pd.DataFrame:
    df_pp = _dataframe_seguro_carregador("prova_paulista")
    return _filtrar_aluno_df(df_pp, nome, ra, turma)


def _resumo_mapao_aluno(nome: str, ra: str = "", turma: str = "") -> pd.DataFrame:
    df_mapao = _dataframe_seguro_carregador("mapao")
    return _filtrar_aluno_df(df_mapao, nome, ra, turma)


def _resumo_ocorrencias_aluno(nome: str, ra: str = "", turma: str = "") -> pd.DataFrame:
    df_oc = _dataframe_seguro_carregador("ocorrencias")
    return _filtrar_aluno_df(df_oc, nome, ra, turma)


def _formatar_numero_pedagogico(valor) -> str:
    if valor in (None, "", "None"):
        return ""
    try:
        num = float(str(valor).replace(",", "."))
        if pd.isna(num):
            return ""
        if abs(num - round(num)) < 0.001:
            return str(int(round(num)))
        return f"{num:.1f}".replace(".", ",")
    except Exception:
        return str(valor or "")


def _mapao_componentes_objeto(valor):
    """Converte o campo Componentes do Mapão para dict, aceitando JSON, dict ou lista."""
    if isinstance(valor, dict):
        return valor
    if isinstance(valor, list):
        convertido = {}
        for item in valor:
            if isinstance(item, dict):
                nome = item.get("componente") or item.get("disciplina") or item.get("nome")
                if nome:
                    convertido[str(nome)] = item
        return convertido
    texto = str(valor or "").strip()
    if not texto or texto.lower() in {"nan", "none", "null"}:
        return {}
    try:
        obj = json.loads(texto)
        if isinstance(obj, dict):
            return obj
        if isinstance(obj, list):
            return _mapao_componentes_objeto(obj)
    except Exception:
        pass
    return {}


def _valor_numerico_ou_texto(valor):
    """Formata menção/frequência mantendo texto quando não for número."""
    if valor in (None, "", "None"):
        return ""
    try:
        num = _parse_numero_br(valor)
        if num is None or pd.isna(num):
            return str(valor or "").strip()
        if abs(num - round(num)) < 0.001:
            return str(int(round(num)))
        return f"{num:.1f}".replace(".", ",")
    except Exception:
        return str(valor or "").strip()


def _resumo_mapao_tutoria_aluno(nome: str, ra: str = "", turma: str = "") -> dict:
    """Busca situação, frequência, faltas e notas do Mapão para exibir no Caderno de Tutoria."""
    df_mapao = _resumo_mapao_aluno(nome, ra, turma)
    if df_mapao is None or df_mapao.empty:
        return {}
    base = df_mapao.copy()

    # Usa a última linha salva/importada para o estudante. Se houver mais de um bimestre,
    # a tabela de rendimento abaixo continua preenchendo cada bimestre componente a componente.
    row = base.iloc[-1]

    frequencia = None
    for col in ["Frequência (%)", "frequencia_percentual", "frequencia", "Frequência"]:
        if col in row.index:
            frequencia = _parse_numero_br(row.get(col))
            if frequencia is not None:
                break

    faltas = None
    for col in ["Faltas", "faltas"]:
        if col in row.index:
            faltas = _parse_numero_br(row.get(col))
            if faltas is not None:
                break

    total_aulas = None
    for col in ["Total de Aulas", "total_aulas"]:
        if col in row.index:
            total_aulas = _parse_numero_br(row.get(col))
            if total_aulas is not None:
                break

    # Se por algum motivo a frequência não veio do Supabase, tenta recalcular por faltas/total de aulas.
    if frequencia is None and faltas is not None and total_aulas and total_aulas > 0:
        frequencia = round(max(0, 100 - (faltas / total_aulas * 100)), 1)

    notas_baixas = str(row.get("Notas abaixo de cinco", "") or row.get("notas_abaixo_cinco", "") or "").strip()
    if notas_baixas.startswith("[") or notas_baixas.startswith("{"):
        try:
            obj = json.loads(notas_baixas)
            if isinstance(obj, list):
                notas_baixas = ", ".join(
                    f"{str(i.get('componente','')).strip()} ({_valor_numerico_ou_texto(i.get('mencao',''))})"
                    for i in obj if isinstance(i, dict)
                )
        except Exception:
            pass

    return {
        "situacao": str(row.get("Situação", "") or row.get("situacao", "") or "").strip(),
        "frequencia": frequencia,
        "faltas": faltas,
        "faltas_anuais": _parse_numero_br(row.get("Faltas anuais", row.get("faltas_anuais", ""))) if ("Faltas anuais" in row.index or "faltas_anuais" in row.index) else faltas,
        "total_aulas": total_aulas,
        "notas_abaixo_de_cinco": notas_baixas,
        "bimestre": str(row.get("Bimestre", "") or "").strip(),
    }


def _rendimento_automatico_aluno(nome: str, ra: str = "", turma: str = "") -> dict:
    """Monta rendimento por componente usando somente o Mapão.

    O caderno de Tutoria deve mostrar apenas as notas/menções da sala vindas do Mapão.
    A Prova Paulista pode continuar sendo usada em outras páginas/relatórios, mas não entra
    nesta tabela de rendimento para evitar mistura entre nota da sala e PP.
    """
    rendimento = {disc: _modelo_rendimento_disciplina() for disc in DISCIPLINAS_CADERNO_TUTORIA}

    df_mapao = _resumo_mapao_aluno(nome, ra, turma)
    for _, row in df_mapao.iterrows():
        bim = _bimestre_para_coluna_caderno(row.get("Bimestre", ""))
        componentes = _mapao_componentes_objeto(row.get("Componentes", {}))
        if isinstance(componentes, dict):
            for comp, dados in componentes.items():
                disc = _componente_para_disciplina_caderno(comp)
                if disc not in rendimento:
                    continue
                if isinstance(dados, dict):
                    mencao = _valor_numerico_ou_texto(dados.get("mencao", ""))
                else:
                    mencao = _valor_numerico_ou_texto(dados)
                if mencao:
                    _rendimento_set_nota_sala(rendimento[disc], bim, mencao)

    for disc, dados in rendimento.items():
        dados["RESULTADO FINAL"] = _rendimento_resultado_final(dados)
    return rendimento

def _mesclar_rendimento_sem_perder_manual(rendimento_atual: dict, rendimento_auto: dict) -> dict:
    mesclado = json.loads(json.dumps(rendimento_atual or {}, ensure_ascii=False)) if isinstance(rendimento_atual, dict) else {}
    for disc in DISCIPLINAS_CADERNO_TUTORIA:
        mesclado.setdefault(disc, _modelo_rendimento_disciplina())
        auto = (rendimento_auto or {}).get(disc, {}) or {}
        for bim in BIMESTRES_CADERNO_TUTORIA:
            atual_limpo = _rendimento_get_nota_sala(mesclado[disc], bim)
            auto_limpo = _rendimento_get_nota_sala(auto, bim)
            valor_original = str(mesclado[disc].get(bim, "") or mesclado[disc].get(f"{bim} - Nota da sala", "") or "")
            valor_sujo_antigo = bool(re.search(r"map[ãa]o\s*:|PP\s*:", valor_original, flags=re.I))
            if auto_limpo and (not atual_limpo or valor_sujo_antigo):
                _rendimento_set_nota_sala(mesclado[disc], bim, auto_limpo)
            else:
                _rendimento_set_nota_sala(mesclado[disc], bim, atual_limpo)
        mesclado[disc]["RESULTADO FINAL"] = _rendimento_resultado_final(mesclado[disc])
    return mesclado


def _extrair_primeiro_numero_texto(valor):
    """Extrai o primeiro número de um texto como '8 | PP: 70%' ou 'Mapão: 7'."""
    if valor in (None, "", "None"):
        return None
    if isinstance(valor, (int, float)) and not pd.isna(valor):
        return float(valor)
    texto = str(valor).strip()
    if not texto:
        return None
    match = re.search(r"-?\d+(?:[\.,]\d+)?", texto)
    if not match:
        return None
    try:
        return float(match.group(0).replace(",", "."))
    except Exception:
        return None


def _pontuar_mapao_media(media, peso_disponivel: float = 40.0, qtd_notas_baixas: int = 0) -> dict:
    """Pontua as notas gerais do Mapão, com teto de 40 pontos.

    Regra gamificada atual:
    - notas gerais valem até 40 pontos;
    - média 0 a 10 vira 0 a 40 pontos;
    - cada componente/nota abaixo de 5 reduz 10 pontos;
    - se não houver dado, não pontua e não penaliza.
    """
    if media is None:
        return {"bruto": 0.0, "penalidade": 0.0, "liquido": 0.0, "tem_dado": False, "notas_baixas": 0}
    try:
        media = float(media)
    except Exception:
        return {"bruto": 0.0, "penalidade": 0.0, "liquido": 0.0, "tem_dado": False, "notas_baixas": 0}
    media = max(0.0, min(10.0, media))
    bruto = round((media / 10.0) * float(peso_disponivel), 1)
    try:
        qtd_notas_baixas = int(qtd_notas_baixas or 0)
    except Exception:
        qtd_notas_baixas = 0
    penalidade = float(max(0, qtd_notas_baixas) * 10)
    liquido = round(max(0.0, min(float(peso_disponivel), bruto - penalidade)), 1)
    return {"bruto": bruto, "penalidade": penalidade, "liquido": liquido, "tem_dado": True, "notas_baixas": qtd_notas_baixas}


def _pontuar_prova_percentual(percentual, peso_disponivel: float = 40.0) -> dict:
    """Pontua a Prova Paulista, com teto de 40 pontos.

    Regra gamificada atual:
    - Prova Paulista vale até 40 pontos;
    - percentual 0 a 100 vira 0 a 40 pontos;
    - abaixo de 50% reduz 10 pontos;
    - se não houver dado, não pontua e não penaliza.
    """
    if percentual is None:
        return {"bruto": 0.0, "penalidade": 0.0, "liquido": 0.0, "tem_dado": False}
    try:
        percentual = float(percentual)
    except Exception:
        return {"bruto": 0.0, "penalidade": 0.0, "liquido": 0.0, "tem_dado": False}
    percentual = max(0.0, min(100.0, percentual))
    bruto = round((percentual / 100.0) * float(peso_disponivel), 1)
    penalidade = 10.0 if percentual < 50 else 0.0
    liquido = round(max(0.0, min(float(peso_disponivel), bruto - penalidade)), 1)
    return {"bruto": bruto, "penalidade": penalidade, "liquido": liquido, "tem_dado": True}


def _status_direitos_pontuacao(pontos) -> str:
    try:
        pontos = float(pontos)
    except Exception:
        return "Sem pontuação"
    return "Direitos mantidos" if pontos >= 70 else "Perde direitos"


# Compatibilidade com versões anteriores do código.
def _pontos_por_media_global(media):
    return _pontuar_mapao_media(media, 40.0).get("liquido", 0.0)


def _pontos_por_percentual_prova(percentual):
    return _pontuar_prova_percentual(percentual, 40.0).get("liquido", 0.0)


def _media_global_mapao_de_df(df_mapao: pd.DataFrame) -> dict:
    if df_mapao is None or df_mapao.empty:
        return {}
    base = df_mapao.copy()
    row = base.iloc[-1]
    componentes = _mapao_componentes_objeto(row.get("Componentes", {}))
    notas = []
    detalhes = []
    if isinstance(componentes, dict):
        for comp, dados in componentes.items():
            mencao_bruta = (dados or {}).get("mencao", "") if isinstance(dados, dict) else dados
            nota = _parse_numero_br(mencao_bruta)
            if nota is None:
                nota = _extrair_primeiro_numero_texto(mencao_bruta)
            if nota is None:
                continue
            notas.append(float(nota))
            detalhes.append({
                "componente": _componente_para_disciplina_caderno(comp),
                "nota": float(nota),
            })
    if not notas:
        return {}
    media = round(sum(notas) / len(notas), 2)
    notas_baixas = sum(1 for n in notas if float(n) < 5)
    return {
        "media": media,
        "quantidade_componentes": len(notas),
        "notas_baixas": notas_baixas,
        "bimestre": str(row.get("Bimestre", "") or "").strip(),
        "detalhes": detalhes,
    }


def _percentual_global_prova_de_df(df_pp: pd.DataFrame):
    if df_pp is None or df_pp.empty:
        return None
    for col in ["Acertos", "Percentual", "acertos_percentual"]:
        if col in df_pp.columns:
            serie = pd.to_numeric(
                df_pp[col].astype(str).str.replace("%", "", regex=False).str.replace(",", ".", regex=False),
                errors="coerce"
            ).dropna()
            if not serie.empty:
                return float(serie.iloc[-1])
    return None


def _calcular_pontuacao_estudante_em_bases(nome: str, ra: str = "", turma: str = "", df_mapao=None, df_pp=None, df_oc=None) -> dict:
    """Calcula a pontuação gamificada do estudante, limitada a 100 pontos.

    Regra atual:
    - Prova Paulista: até 40 pontos; abaixo de 50% perde 10 pontos dentro desse bloco.
    - Notas gerais do Mapão: até 40 pontos; cada nota/componente abaixo de 5 perde 10 pontos dentro desse bloco.
    - Convivência: até 20 pontos por não ter ocorrência; cada ocorrência reduz 10 pontos desse bloco.
    - Pontuação final fica sempre entre 0 e 100. Abaixo de 70 perde direitos.
    """
    if df_mapao is None:
        df_mapao = _resumo_mapao_aluno(nome, ra, turma)
    if df_pp is None:
        df_pp = _resumo_prova_paulista_aluno(nome, ra, turma)
    if df_oc is None:
        df_oc = _resumo_ocorrencias_aluno(nome, ra, turma)

    info_mapao = _media_global_mapao_de_df(df_mapao)
    media_mapao = info_mapao.get("media")
    notas_baixas = int(info_mapao.get("notas_baixas", 0) or 0)
    percentual_pp = _percentual_global_prova_de_df(df_pp)

    mapao_pts = _pontuar_mapao_media(media_mapao, 40.0, notas_baixas)
    pp_pts = _pontuar_prova_percentual(percentual_pp, 40.0)

    ocorrencias_total = 0 if df_oc is None or df_oc.empty else int(len(df_oc))
    pontos_convivencia_bruto = 20.0
    desconto_ocorrencias = float(ocorrencias_total * 10)
    pontos_convivencia = round(max(0.0, pontos_convivencia_bruto - desconto_ocorrencias), 1)

    pontuacao_final = round(max(0.0, min(100.0, mapao_pts.get("liquido", 0.0) + pp_pts.get("liquido", 0.0) + pontos_convivencia)), 1)

    return {
        "base_inicial": 100.0,
        "fontes_disponiveis": int(media_mapao is not None) + int(percentual_pp is not None),
        "ocorrencias_total": ocorrencias_total,
        "desconto_ocorrencias": desconto_ocorrencias,
        "pontos_convivencia": pontos_convivencia,
        "media_global_mapao": media_mapao,
        "peso_mapao": 40.0,
        "pontos_mapao": mapao_pts.get("liquido", 0.0),
        "pontos_brutos_mapao": mapao_pts.get("bruto", 0.0),
        "penalidade_mapao": mapao_pts.get("penalidade", 0.0),
        "notas_baixas_mapao": notas_baixas,
        "bimestre_mapao": info_mapao.get("bimestre", ""),
        "quantidade_componentes_mapao": info_mapao.get("quantidade_componentes", 0),
        "percentual_prova_paulista": percentual_pp,
        "peso_prova_paulista": 40.0,
        "pontos_prova_paulista": pp_pts.get("liquido", 0.0),
        "pontos_brutos_prova_paulista": pp_pts.get("bruto", 0.0),
        "penalidade_prova_paulista": pp_pts.get("penalidade", 0.0),
        "pontuacao_final": pontuacao_final,
        "status_direitos": _status_direitos_pontuacao(pontuacao_final),
    }


def _ranking_pontuacao_turma(df_alunos_turma: pd.DataFrame) -> pd.DataFrame:
    if df_alunos_turma is None or df_alunos_turma.empty:
        return pd.DataFrame()
    df_mapao_base = _dataframe_seguro_carregador("mapao")
    df_pp_base = _dataframe_seguro_carregador("prova_paulista")
    df_oc_base = _dataframe_seguro_carregador("ocorrencias")
    linhas = []
    for _, aluno in df_alunos_turma.iterrows():
        nome = str(aluno.get("nome", "") or "").strip()
        ra = str(aluno.get("ra", "") or "").strip()
        turma = str(aluno.get("turma", "") or "").strip()
        pont = _calcular_pontuacao_estudante_em_bases(
            nome,
            ra,
            turma,
            _filtrar_aluno_df(df_mapao_base, nome, ra, turma),
            _filtrar_aluno_df(df_pp_base, nome, ra, turma),
            _filtrar_aluno_df(df_oc_base, nome, ra, turma),
        )
        linhas.append({
            "Estudante": nome,
            "RA": ra,
            "Turma": turma,
            "Pontuação": pont.get("pontuacao_final", 0),
            "Status": pont.get("status_direitos", _status_direitos_pontuacao(pont.get("pontuacao_final", 0))),
            "PP pts": pont.get("pontos_prova_paulista", 0),
            "Notas pts": pont.get("pontos_mapao", 0),
            "Convivência pts": pont.get("pontos_convivencia", 0),
            "Ocorrências": pont.get("ocorrencias_total", 0),
            "Notas abaixo de 5": pont.get("notas_baixas_mapao", 0),
            "Média global Mapão": pont.get("media_global_mapao"),
            "Prova Paulista (%)": pont.get("percentual_prova_paulista"),
        })
    ranking = pd.DataFrame(linhas)
    if ranking.empty:
        return ranking
    for col in ["Pontuação", "PP pts", "Notas pts", "Convivência pts", "Ocorrências", "Notas abaixo de 5", "Média global Mapão", "Prova Paulista (%)"]:
        if col in ranking.columns:
            ranking[col] = pd.to_numeric(ranking[col], errors="coerce")
    ranking = ranking.sort_values(["Pontuação", "Média global Mapão", "Prova Paulista (%)", "Estudante"], ascending=[False, False, False, True]).reset_index(drop=True)
    ranking.insert(0, "Posição", range(1, len(ranking) + 1))
    return ranking


def _ranking_pontuacao_geral(df_alunos_base: pd.DataFrame | None = None) -> pd.DataFrame:
    """Ranking gamificado de todos os estudantes, limitado a 100 pontos."""
    if df_alunos_base is None:
        df_alunos_base = globals().get("df_alunos", pd.DataFrame())
    if df_alunos_base is None or df_alunos_base.empty:
        return pd.DataFrame()
    return _ranking_pontuacao_turma(df_alunos_base)


def _ranking_pontuacao_turmas(df_alunos_base: pd.DataFrame | None = None) -> pd.DataFrame:
    """Ranking justo das salas: usa média da pontuação dos estudantes, não soma bruta."""
    ranking = _ranking_pontuacao_geral(df_alunos_base)
    if ranking.empty or "Turma" not in ranking.columns:
        return pd.DataFrame()
    base = ranking.copy()
    base["Pontuação"] = pd.to_numeric(base["Pontuação"], errors="coerce")
    base["Abaixo de 70"] = base["Pontuação"] < 70
    agrupado = base.groupby("Turma", dropna=False).agg(
        **{
            "Média da sala": ("Pontuação", "mean"),
            "Estudantes avaliados": ("Estudante", "count"),
            "Estudantes abaixo de 70": ("Abaixo de 70", "sum"),
            "Maior pontuação": ("Pontuação", "max"),
            "Menor pontuação": ("Pontuação", "min"),
        }
    ).reset_index()
    agrupado["% abaixo de 70"] = agrupado.apply(
        lambda r: round((float(r["Estudantes abaixo de 70"]) / float(r["Estudantes avaliados"]) * 100), 1)
        if float(r["Estudantes avaliados"] or 0) > 0 else 0.0,
        axis=1,
    )
    agrupado["Média da sala"] = agrupado["Média da sala"].round(1)
    agrupado["Maior pontuação"] = agrupado["Maior pontuação"].round(1)
    agrupado["Menor pontuação"] = agrupado["Menor pontuação"].round(1)
    agrupado = agrupado.sort_values(["Média da sala", "Estudantes avaliados", "Turma"], ascending=[False, False, True]).reset_index(drop=True)
    agrupado.insert(0, "Posição", range(1, len(agrupado) + 1))
    agrupado["Premiação semanal"] = agrupado["Posição"].apply(lambda p: "🏆 Sala da semana" if int(p) == 1 else "")
    agrupado["Premiação mensal"] = agrupado["Posição"].apply(lambda p: "🏆 Sala do mês" if int(p) == 1 else "")
    return agrupado


def _formatar_ranking_pontuacao_para_exibir(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame()
    saida = df.copy()
    for col in ["Pontuação", "Média global Mapão", "Prova Paulista (%)", "Média da sala", "Maior pontuação", "Menor pontuação", "% abaixo de 70"]:
        if col in saida.columns:
            saida[col] = saida[col].apply(lambda v: _formatar_numero_pedagogico(v) if pd.notna(v) else "")
    return saida


def _dados_integrados_estudante(nome: str, ra: str = "", turma: str = "") -> dict:
    df_pp = _resumo_prova_paulista_aluno(nome, ra, turma)
    df_mapao = _resumo_mapao_aluno(nome, ra, turma)
    df_oc = _resumo_ocorrencias_aluno(nome, ra, turma)
    frequencia = None
    if not df_mapao.empty and "Frequência (%)" in df_mapao.columns:
        serie_freq = pd.to_numeric(df_mapao["Frequência (%)"].astype(str).str.replace(",", "."), errors="coerce").dropna()
        if not serie_freq.empty:
            frequencia = float(serie_freq.iloc[-1])
    acertos_pp = None
    if not df_pp.empty and "Acertos" in df_pp.columns:
        serie_acc = pd.to_numeric(df_pp["Acertos"].astype(str).str.replace(",", "."), errors="coerce").dropna()
        if not serie_acc.empty:
            acertos_pp = float(serie_acc.iloc[-1])
    ocorr_graves = 0
    if not df_oc.empty and "gravidade" in df_oc.columns:
        ocorr_graves = int(df_oc["gravidade"].astype(str).apply(lambda v: normalizar_texto(v) in {"GRAVE", "GRAVISSIMA", "GRAVÍSSIMA"}).sum())
    pontuacao = _calcular_pontuacao_estudante_em_bases(nome, ra, turma, df_mapao, df_pp, df_oc)
    return {
        "prova_paulista": df_pp,
        "mapao": df_mapao,
        "ocorrencias": df_oc,
        "frequencia_mapao": frequencia,
        "acertos_pp": acertos_pp,
        "ocorrencias_graves": ocorr_graves,
        "rendimento_auto": _rendimento_automatico_aluno(nome, ra, turma),
        "pontuacao": pontuacao,
    }


def _render_painel_integrado_estudante(nome: str, ra: str, turma: str, dados: dict):
    df_pp = dados.get("prova_paulista", pd.DataFrame())
    df_mapao = dados.get("mapao", pd.DataFrame())
    df_oc = dados.get("ocorrencias", pd.DataFrame())
    freq = dados.get("frequencia_mapao")
    acc = dados.get("acertos_pp")
    st.markdown("### 🔗 Dados integrados do estudante")
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Prova Paulista", len(df_pp))
    c2.metric("Mapão", len(df_mapao))
    c3.metric("Ocorrências", len(df_oc))
    c4.metric("Ocorrências graves", dados.get("ocorrencias_graves", 0))
    resumo = []
    if freq is not None:
        resumo.append(f"Frequência mais recente no Mapão: **{_formatar_numero_pedagogico(freq)}%**")
    if acc is not None:
        resumo.append(f"Acertos mais recentes na Prova Paulista: **{_formatar_numero_pedagogico(acc)}%**")
    if resumo:
        st.info(" · ".join(resumo))

    pontuacao = dados.get("pontuacao", {}) or {}
    if pontuacao:
        st.markdown("### 🏅 Pontuação gamificada automática")
        pc1, pc2, pc3, pc4, pc5 = st.columns(5)
        pontos_total_txt = _formatar_numero_pedagogico(pontuacao.get("pontuacao_final")) or "0"
        pc1.metric("Pontuação total", f"{pontos_total_txt}/100")
        pc2.metric("Direitos", pontuacao.get("status_direitos", _status_direitos_pontuacao(pontuacao.get("pontuacao_final", 0))))
        pc3.metric("Ocorrências", pontuacao.get("ocorrencias_total", 0), delta=f"-{_formatar_numero_pedagogico(pontuacao.get('desconto_ocorrencias')) or '0'} pts")
        media_mapao_txt = _formatar_numero_pedagogico(pontuacao.get("media_global_mapao")) or "-"
        pc4.metric("Mapão", media_mapao_txt, delta=f"{_formatar_numero_pedagogico(pontuacao.get('pontos_mapao')) or '0'} pts")
        pp_txt = _formatar_numero_pedagogico(pontuacao.get("percentual_prova_paulista"))
        pc5.metric("Prova Paulista", f"{pp_txt}%" if pp_txt else "-", delta=f"{_formatar_numero_pedagogico(pontuacao.get('pontos_prova_paulista')) or '0'} pts")
        st.caption("Regra aplicada: pontuação máxima 100. Prova Paulista vale até 40 pontos, notas gerais/Mapão até 40 pontos e convivência até 20 pontos. Cada ocorrência reduz 10 pontos; cada nota abaixo de 5 reduz 10 pontos; Prova Paulista abaixo de 50% reduz 10 pontos; abaixo de 70 perde direitos.")

    with st.expander("Ver dados integrados deste estudante", expanded=False):
        tab1, tab2, tab3, tab4 = st.tabs(["📊 Prova Paulista", "🗺️ Mapão", "📋 Ocorrências", "📚 Rendimento automático"])
        with tab1:
            if df_pp.empty:
                st.caption("Nenhum dado da Prova Paulista localizado para este estudante.")
            else:
                st.dataframe(df_pp, use_container_width=True, hide_index=True, height=260)
        with tab2:
            if df_mapao.empty:
                st.caption("Nenhum dado do Mapão localizado para este estudante.")
            else:
                st.dataframe(df_mapao, use_container_width=True, hide_index=True, height=260)
        with tab3:
            if df_oc.empty:
                st.caption("Nenhuma ocorrência localizada para este estudante.")
            else:
                cols = [c for c in ["data", "turma", "categoria", "gravidade", "relato", "descricao", "encaminhamento", "professor"] if c in df_oc.columns]
                st.dataframe(df_oc[cols] if cols else df_oc, use_container_width=True, hide_index=True, height=260)
        with tab4:
            rend = dados.get("rendimento_auto", {}) or {}
            linhas = [{"COMPONENTE CURRICULAR": d, **rend.get(d, {})} for d in DISCIPLINAS_CADERNO_TUTORIA]
            st.dataframe(pd.DataFrame(linhas), use_container_width=True, hide_index=True, height=320)


# ---------- Indicadores e histórico ----------
def _metricas_caderno_tutoria(cadernos: dict, professor: str, estudantes: list[dict]) -> dict:
    chaves = []
    for e in estudantes or []:
        chaves.append(_chave_caderno_tutoria(professor, e.get("nome", ""), e.get("turma", "")))
    existentes = [cadernos.get(k, {}) for k in chaves if isinstance(cadernos.get(k), dict)]
    individuais = sum(len(c.get("tutoria_individual", []) or []) for c in existentes)
    coletivas = sum(len(c.get("tutoria_coletiva", []) or []) for c in existentes)
    preenchidos = sum(1 for c in existentes if c.get("atualizado_em"))
    assinados = sum(1 for c in existentes if (c.get("assinaturas_digitais", {}) or {}).get("professor_nome"))
    return {
        "tutorados": len(estudantes or []),
        "cadernos_salvos": preenchidos,
        "pendentes": max(0, len(estudantes or []) - preenchidos),
        "registros_individuais": individuais,
        "encontros_coletivos": coletivas,
        "assinados": assinados,
    }


def _render_metricas_caderno_tutoria(cadernos: dict, professor: str, estudantes: list[dict]):
    m = _metricas_caderno_tutoria(cadernos, professor, estudantes)
    cols = st.columns(6)
    cols[0].metric("Tutorados", m["tutorados"])
    cols[1].metric("Cadernos salvos", m["cadernos_salvos"])
    cols[2].metric("Pendentes", m["pendentes"])
    cols[3].metric("Individuais", m["registros_individuais"])
    cols[4].metric("Coletivos", m["encontros_coletivos"])
    cols[5].metric("Assinados", m["assinados"])


def _filtrar_df_por_aluno(df: pd.DataFrame, aluno: str, turma: str = "") -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame()
    base = df.copy()
    aluno_norm = normalizar_texto(aluno)
    mask = pd.Series(False, index=base.index)
    for col in ["aluno", "nome", "estudante"]:
        if col in base.columns:
            mask = mask | (base[col].astype(str).map(normalizar_texto) == aluno_norm)
    if turma and "turma" in base.columns:
        # Mantém por nome como principal. Turma apenas ajuda quando a coluna existir.
        pass
    return base[mask].copy()


def _render_historico_integrado_aluno(aluno: str, turma: str, caderno: dict):
    st.markdown("### 📁 Histórico integrado do estudante")
    col1, col2, col3 = st.columns(3)
    col1.metric("Registros individuais", len(caderno.get("tutoria_individual", []) or []))
    col2.metric("Encontros coletivos", len(caderno.get("tutoria_coletiva", []) or []))
    col3.metric("Atualização", caderno.get("atualizado_em") or "Não salvo")

    st.markdown("#### Tutoria individual")
    if caderno.get("tutoria_individual"):
        st.dataframe(pd.DataFrame(caderno.get("tutoria_individual", [])), use_container_width=True, hide_index=True)
    else:
        st.info("Nenhum registro individual no caderno.")

    st.markdown("#### Tutoria coletiva")
    coletivas = caderno.get("tutoria_coletiva", []) or []
    if coletivas:
        resumo = []
        for r in coletivas:
            resumo.append({"Data": r.get("data", ""), "Nº": r.get("numero_encontro", ""), "Objetivo": r.get("objetivo_encontro", ""), "Observações": r.get("observacoes", "")})
        st.dataframe(pd.DataFrame(resumo), use_container_width=True, hide_index=True)
    else:
        st.info("Nenhum encontro coletivo no caderno.")

    with st.expander("Ocorrências do estudante", expanded=False):
        try:
            df_oc = carregar_ocorrencias()
            df_aluno = _filtrar_df_por_aluno(df_oc, aluno, turma)
            if df_aluno.empty:
                st.info("Nenhuma ocorrência localizada para este estudante.")
            else:
                cols = [c for c in ["data", "aluno", "turma", "categoria", "gravidade", "relato", "encaminhamento", "professor"] if c in df_aluno.columns]
                st.dataframe(df_aluno[cols], use_container_width=True, hide_index=True)
        except Exception as e:
            st.warning(f"Não foi possível carregar ocorrências: {e}")

    with st.expander("Relatórios do estudante", expanded=False):
        try:
            df_rel = carregar_relatorios_estudantes()
            df_aluno = _filtrar_df_por_aluno(df_rel, aluno, turma)
            if df_aluno.empty:
                st.info("Nenhum relatório localizado para este estudante.")
            else:
                st.dataframe(df_aluno, use_container_width=True, hide_index=True)
        except Exception as e:
            st.warning(f"Não foi possível carregar relatórios: {e}")


# ---------- Assinaturas digitais ----------
def _salvar_upload_assinatura(arquivo) -> str:
    if not arquivo:
        return ""
    import base64
    conteudo = arquivo.read()
    return base64.b64encode(conteudo).decode("utf-8") if conteudo else ""


def _imagem_assinatura_reportlab(b64: str, largura: float = 5.0*cm, altura: float = 1.6*cm):
    if not b64:
        return None
    try:
        import base64
        bio = BytesIO(base64.b64decode(b64))
        img = Image(bio, width=largura, height=altura)
        return img
    except Exception:
        return None


def _render_assinaturas_digitais(caderno: dict, chave: str):
    st.markdown("### 🖊️ Assinaturas digitais")
    st.caption("Use texto, imagem enviada ou ambos. A assinatura será incluída no PDF do caderno.")
    assinaturas = caderno.setdefault("assinaturas_digitais", {})
    col1, col2 = st.columns(2)
    with col1:
        st.markdown("#### Professor(a) / Tutor(a)")
        assinaturas["professor_nome"] = st.text_input("Nome para assinatura do professor", value=assinaturas.get("professor_nome") or caderno.get("professor", ""), key=f"ass_prof_nome_{chave}")
        assinaturas["professor_data"] = st.text_input("Data da assinatura do professor", value=assinaturas.get("professor_data", datetime.now().strftime("%d/%m/%Y")), key=f"ass_prof_data_{chave}")
        upload_prof = st.file_uploader("Imagem da assinatura do professor (PNG/JPG)", type=["png", "jpg", "jpeg"], key=f"ass_prof_upload_{chave}")
        if upload_prof:
            assinaturas["professor_imagem_b64"] = _salvar_upload_assinatura(upload_prof)
        if assinaturas.get("professor_imagem_b64"):
            import base64
            st.image(BytesIO(base64.b64decode(assinaturas["professor_imagem_b64"])), caption="Assinatura do professor", width=280)
    with col2:
        st.markdown("#### Gestão / Coordenação")
        assinaturas["gestao_nome"] = st.text_input("Nome para assinatura da gestão", value=assinaturas.get("gestao_nome", ""), key=f"ass_gest_nome_{chave}")
        assinaturas["gestao_data"] = st.text_input("Data da assinatura da gestão", value=assinaturas.get("gestao_data", datetime.now().strftime("%d/%m/%Y")), key=f"ass_gest_data_{chave}")
        upload_gest = st.file_uploader("Imagem da assinatura da gestão (PNG/JPG)", type=["png", "jpg", "jpeg"], key=f"ass_gest_upload_{chave}")
        if upload_gest:
            assinaturas["gestao_imagem_b64"] = _salvar_upload_assinatura(upload_gest)
        if assinaturas.get("gestao_imagem_b64"):
            import base64
            st.image(BytesIO(base64.b64decode(assinaturas["gestao_imagem_b64"])), caption="Assinatura da gestão", width=280)
    caderno["assinaturas_digitais"] = assinaturas


